t["Small victories still count."] = "\\u0627\\u0644\\u0627\\u0646\\u062A\\u0635\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629 \\u0644\\u0633\\u0627 \\u0628\\u062A\\u0646\\u062D\\u0633\\u0628."
t["Smell of bleach and worse. Let's be quick."] = "\\u0631\\u064A\\u062D\\u0629 \\u0643\\u0644\\u0648\\u0631 \\u0648\\u0623\\u0639\\u0648\\u0633. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u0635 \\u0628\\u0633\\u0631\\u0639\\u0629."
t["Smell of old paper. Almost like nothing happened."] = "\\u0631\\u064A\\u062D\\u0629 \\u0648\\u0631\\u0642 \\u0642\\u062F\\u064A\\u0645. \\u0643\\u0623\\u0646 \\u0645\\u0627 \\u0635\\u0627\\u0631 \\u0634\\u064A."
t["Smell that? That's the state flower."] = "\\u0634\\u0627\\u0645\\u0645\\u061F \\u0647\\u064A \\u0632\\u0647\\u0631\\u0629 \\u0627\\u0644\\u0648\\u0644\\u0627\\u064A\\u0629."
t["Smells like a ballgame got rained out. Every game, forever."] = "\\u0631\\u064A\\u062D\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0645\\u0627\\u062A\\u0634 \\u0627\\u0646\\u0644\\u063A\\u0649 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0637\\u0631. \\u0643\\u0644 \\u0645\\u0627\\u062A\\u0634\\u060C \\u0644\\u0644\\u0623\\u0628\\u062F."
t["Smells like basic training. I didn't miss it."] = "\\u0631\\u064A\\u062D\\u0629 \\u0627\\u0644\\u062A\\u062F\\u0631\\u064A\\u0628 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064A. \\u0645\\u0627 \\u0627\\u0634\\u062A\\u0642\\u062A\\u0644\\u0647."
t["Smells like oil and regret. Good tools, though."] = "\\u0631\\u064A\\u062D\\u062A\\u0647 \\u0632\\u064A\\u062A \\u0648\\u0646\\u062F\\u0645. \\u0628\\u0633 \\u0627\\u0644\\u0639\\u062F\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629."
t["So that is how they do it. Huh."] = "\\u0625\\u064A\\u060C \\u0647\\u064A\\u0643 \\u0628\\u064A\\u0639\\u0645\\u0644\\u0648\\u0647\\u0627 \\u064A\\u0639\\u0646\\u064A. \\u0639\\u062C\\u064A\\u0628."
t["Soap in my eyes and ghosts in the hall..."] = "\\u0635\\u0627\\u0628\\u0648\\u0646 \\u0628\\u0639\\u064A\\u0648\\u0646\\u064A \\u0648\\u0623\\u0634\\u0628\\u0627\\u062D \\u0628\\u0627\\u0644\\u0645\\u0645\\u0631..."
t["Soap or no soap, this is overdue."] = "\\u0628\\u0635\\u0627\\u0628\\u0648\\u0646 \\u0623\\u0648 \\u0628\\u0644\\u0627 \\u0635\\u0627\\u0628\\u0648\\u0646\\u060C \\u0647\\u0627\\u062F \\u062A\\u0623\\u062E\\u0631 \\u0643\\u062A\\u064A\\u0631."
t["Some days I envy them. No hunger. No choices. No sore feet."] = "\\u0641\\u064A \\u0623\\u064A\\u0627\\u0645 \\u0628\\u062D\\u0633\\u062F\\u0647\\u0645. \\u0644\\u0627 \\u062C\\u0648\\u0639. \\u0644\\u0627 \\u062E\\u064A\\u0627\\u0631\\u0627\\u062A. \\u0644\\u0627 \\u0648\\u062C\\u0639 \\u0631\\u062C\\u0644\\u064A\\u0646."
t["Some days I forget why we bother. Then I keep working anyway."] = "\\u0641\\u064A \\u0623\\u064A\\u0627\\u0645 \\u0628\\u0646\\u0633\\u0649 \\u0644\\u064A\\u0634 \\u0639\\u0645 \\u0646\\u062A\\u0639\\u0628 \\u062D\\u0627\\u0644\\u0646\\u0627. \\u0648\\u0628\\u0643\\u0645\\u0644 \\u0634\\u063A\\u0644 \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u062D\\u0627\\u0644."
t["Some days I want the fight more than I want to win it."] = "\\u0641\\u064A \\u0623\\u064A\\u0627\\u0645 \\u0628\\u062F\\u064A \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0631\\u0628\\u062D\\u0647."
t["Some moments are easier than others. I still miss %1."] = "\\u0641\\u064A \\u0644\\u062D\\u0638\\u0627\\u062A \\u0623\\u0633\\u0647\\u0644 \\u0645\\u0646 \\u063A\\u064A\\u0631\\u0647\\u0627. \\u0644\\u0633\\u0627 \\u0645\\u0634\\u062A\\u0627\\u0642\\u0629 \\u0644\\u0640%1."
t["Some nights I hear my mother calling. She's been gone for years."] = "\\u0641\\u064A \\u0644\\u064A\\u0627\\u0644\\u064A \\u0628\\u0633\\u0645\\u0639 \\u0623\\u0645\\u064A \\u0639\\u0645 \\u062A\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A. \\u0631\\u0627\\u062D\\u062A \\u0645\\u0646 \\u0633\\u0646\\u064A\\u0646."
t["Some nights a voice over the air is shelter enough."] = "\\u0628\\u0639\\u0636 \\u0627\\u0644\\u0644\\u064A\\u0627\\u0644\\u064A \\u0635\\u0648\\u062A \\u0639\\u0627\\u0644\\u0647\\u0648\\u0627 \\u0628\\u0643\\u0641\\u064A \\u0645\\u0623\\u0648\\u0649."
t["Some nights the quiet sounds like everyone who's gone."] = "\\u0641\\u064A \\u0644\\u064A\\u0627\\u0644\\u064A \\u0627\\u0644\\u0633\\u0643\\u0648\\u062A \\u0635\\u0648\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0643\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0631\\u0627\\u062D\\u0648\\u0627."
t["Some small voice wants me to lie down on the next road. Just because."] = "\\u0641\\u064A \\u0635\\u0648\\u062A \\u0635\\u063A\\u064A\\u0631 \\u0628\\u062F\\u0648 \\u064A\\u0627\\u0646\\u064A \\u0627\\u0646\\u0633\\u062F\\u062D \\u0639\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u062C\\u0627\\u064A. \\u0647\\u064A\\u0643 \\u0628\\u0633."
t["Somebody bought a lottery ticket here. Bad timing."] = "\\u062D\\u062F\\u0627 \\u0627\\u0634\\u062A\\u0631\\u0649 \\u064A\\u0627\\u0646\\u0635\\u064A\\u0628 \\u0645\\u0646 \\u0647\\u0648\\u0646. \\u062A\\u0648\\u0642\\u064A\\u062A \\u0639\\u0627\\u0637\\u0644."
t["Somebody bought this for a party, once."] = "\\u062D\\u062F\\u0627 \\u0627\\u0634\\u062A\\u0631\\u0649 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0644\\u062D\\u0641\\u0644\\u0629\\u060C \\u0645\\u0631\\u0629."
t["Somebody broke this chair in for me. Thank you, stranger."] = "\\u062D\\u062F\\u0627 \\u0637\\u0631\\u0651\\u0627\\u0644\\u064A \\u0647\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A. \\u0634\\u0643\\u0631\\u064B\\u0627 \\u064A\\u0627 \\u063A\\u0631\\u064A\\u0628."
t["Somebody built this high to see trouble coming. Did it help?"] = "\\u062D\\u062F\\u0627 \\u0628\\u0646\\u0649 \\u0647\\u0627\\u0644\\u0639\\u0644\\u0648 \\u0644\\u064A\\u0634\\u0648\\u0641 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0643\\u0644 \\u062C\\u0627\\u064A\\u0629. \\u0646\\u0641\\u0639\\u061F"
t["Somebody cleaned out the good stuff. The vitamins survived. Of course."] = "\\u062D\\u062F\\u0627 \\u0646\\u0636\\u0651\\u0641 \\u0627\\u0644\\u0634\\u063A\\u0644\\u0627\\u062A \\u0627\\u0644\\u0645\\u0646\\u064A\\u062D\\u0629. \\u0627\\u0644\\u0641\\u064A\\u062A\\u0627\\u0645\\u064A\\u0646\\u0627\\u062A \\u0646\\u062C\\u064A\\u062A. \\u0623\\u0643\\u064A\\u062F."
t["Somebody got here first. Somebody always gets here first."] = "\\u062D\\u062F\\u0627 \\u0633\\u0628\\u0642\\u0646\\u0627. \\u062F\\u0627\\u064A\\u0645\\u064B\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0633\\u0628\\u0642."
t["Somebody hung the 'Do Not Disturb' sign. Respect it."] = "\\u062D\\u062F\\u0627 \\u0639\\u0644\\u0651\\u0642 \\u064A\\u0627\\u0641\\u0637\\u0629 \\u0645\\u0645\\u0646\\u0648\\u0639 \\u0627\\u0644\\u0625\\u0632\\u0639\\u0627\\u062C. \\u0627\\u062D\\u062A\\u0631\\u0645\\u0647\\u0627."
