t["Somebody left a car on the lift. Rude."] = "\\u062D\\u062F\\u0627 \\u062A\\u0631\\u0643 \\u0633\\u064A\\u0627\\u0631\\u0629 \\u0639\\u0627\\u0644\\u0631\\u0627\\u0641\\u0639\\u0629. \\u0642\\u0644\\u0629 \\u0630\\u0648\\u0642."
