t["Somebody once taught that one to ride a bike."] = "\\u062D\\u062F\\u0627 \\u0645\\u0631\\u0629 \\u0639\\u0644\\u0651\\u0645 \\u0647\\u062F\\u0627\\u0643 \\u064A\\u0633\\u0648\\u0642 \\u0628\\u0633\\u0643\\u0644\\u064A\\u062A."
