t["Somebody snores like a goddamn chainsaw. Not naming names. It's you."] = "\\u0641\\u064A \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0634\\u062E\\u0631 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0645\\u0646\\u0634\\u0627\\u0631 \\u064A\\u0644\\u0639\\u0646\\u0647. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0633\\u0645\\u0651\\u064A \\u062D\\u062F\\u0627. \\u0625\\u0646\\u062A."
t["Somebody stocked this for a war. Wrong war."] = "\\u062D\\u062F\\u0627 \\u062E\\u0632\\u0651\\u0646 \\u0647\\u0648\\u0646 \\u0644\\u062D\\u0631\\u0628. \\u0627\\u0644\\u062D\\u0631\\u0628 \\u0627\\u0644\\u063A\\u0644\\u0637."
t["Somebody was running tests. The test ran them."] = "\\u062D\\u062F\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0645 \\u064A\\u0639\\u0645\\u0644 \\u062A\\u062C\\u0627\\u0631\\u0628. \\u0627\\u0644\\u062A\\u062C\\u0631\\u0628\\u0629 \\u0639\\u0645\\u0644\\u062A \\u0641\\u064A\\u0647."
