t["Somebody's still flying. I'd rather they weren't doing it over us."] = "\\u0644\\u0633\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0637\\u064A\\u0631. \\u064A\\u0627 \\u0631\\u064A\\u062A \\u0645\\u0648 \\u0641\\u0648\\u0642 \\u0631\\u0627\\u0633\\u0646\\u0627."
t["Somebody's still got a hall pass. Hope it covers the apocalypse."] = "\\u062D\\u062F\\u0627 \\u0644\\u0633\\u0627 \\u0645\\u0639\\u0647 \\u0625\\u0630\\u0646 \\u062E\\u0631\\u0648\\u062C. \\u0625\\u0646 \\u0634\\u0627\\u0621 \\u0627\\u0644\\u0644\\u0647 \\u0628\\u064A\\u063A\\u0637\\u064A \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645."
t["Somebody's still waiting on their spin cycle."] = "\\u062D\\u062F\\u0627 \\u0644\\u0633\\u0627 \\u0645\\u0633\\u062A\\u0646\\u064A \\u062F\\u0648\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0635\\u0631."
