t["Someday someone will drive the next road just for fun."] = "\\u064A\\u0648\\u0645\\u064B\\u0627 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0633\\u0648\\u0642 \\u0639\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u062C\\u0627\\u064A \\u0628\\u0633 \\u0644\\u0644\\u0643\\u064A\\u0641."
t["Someday this is just the old place. I'd like that."] = "\\u064A\\u0648\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0647\\u0627\\u062F \\u0631\\u062D \\u064A\\u0635\\u064A\\u0631 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645. \\u0628\\u062D\\u0628 \\u0647\\u0627\\u0644\\u0634\\u064A."
