t["Someone inside is ill. Don't come any closer."] = "\\u0641\\u064A \\u062D\\u062F\\u0627 \\u062C\\u0648\\u0627 \\u062A\\u0639\\u0628\\u0627\\u0646. \\u0644\\u0627 \\u062A\\u0642\\u0631\\u0628 \\u0623\\u0643\\u062A\\u0631."
t["Someone inside is sick. Keep your distance."] = "\\u0641\\u064A \\u062D\\u062F\\u0627 \\u0645\\u0631\\u064A\\u0636 \\u062C\\u0648\\u0627. \\u062E\\u0644\\u064A\\u0643 \\u0628\\u0639\\u064A\\u062F."
t["Someone is still behind a microphone."] = "\\u0644\\u0633\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0648\\u0631\\u0627 \\u0645\\u0627\\u064A\\u0643\\u0631\\u0648\\u0641\\u0648\\u0646."
