t["Someone needs to say it: that plan fell apart the moment we went inside."] = "\\u0644\\u0627\\u0632\\u0645 \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0648\\u0644\\u0647\\u0627: \\u0627\\u0644\\u062E\\u0637\\u0629 \\u0627\\u0646\\u0647\\u0627\\u0631\\u062A \\u0623\\u0648\\u0644 \\u0645\\u0627 \\u0641\\u062A\\u0646\\u0627 \\u062C\\u0648\\u0627."
t["Someone out there learned the hard way for us."] = "\\u062D\\u062F\\u0627 \\u0628\\u0631\\u0627 \\u062A\\u0639\\u0644\\u0645 \\u0628\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629 \\u0639\\u0646\\u0627."
t["Someone saved %1 for a reason. I'll treat it kindly."] = "\\u062D\\u062F\\u0627 \\u062E\\u0628\\u0651\\u0649 %1 \\u0644\\u0633\\u0628\\u0628. \\u0631\\u062D \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u064A \\u0639\\u0644\\u064A\\u0647."
t["Someone straightened these chairs. I noticed."] = "\\u062D\\u062F\\u0627 \\u0631\\u062A\\u0651\\u0628 \\u0647\\u0627\\u0644\\u0643\\u0631\\u0627\\u0633\\u064A. \\u0627\\u0646\\u062A\\u0628\\u0647\\u062A."
t["Someone's sick. We'd rather ask for distance than need another bed."] = "\\u0641\\u064A \\u062D\\u062F\\u0627 \\u0645\\u0631\\u064A\\u0636. \\u0645\\u0646\\u0641\\u0636\\u0651\\u0644 \\u0646\\u0637\\u0644\\u0628 \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0639\\u0644\\u0649 \\u0625\\u0646\\u0648 \\u0646\\u062D\\u062A\\u0627\\u062C \\u062A\\u062E\\u062A \\u062A\\u0627\\u0646\\u064A."
t["Someone's unwell. Please keep a little room between us."] = "\\u0641\\u064A \\u062D\\u062F\\u0627 \\u062A\\u0639\\u0628\\u0627\\u0646. \\u0644\\u0648 \\u0633\\u0645\\u062D\\u062A \\u062E\\u0644\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627."
t["Something about our plan has to change."] = "\\u0641\\u064A \\u0634\\u064A \\u0628\\u062E\\u0637\\u062A\\u0646\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u062A\\u063A\\u064A\\u0631."
t["Something broke. Keep clear of the opening until we know what follows."] = "\\u0634\\u064A \\u0627\\u0646\\u0643\\u0633\\u0631. \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646 \\u0627\\u0644\\u0641\\u062A\\u062D\\u0629 \\u0644\\u0646\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u062C\\u0627\\u064A \\u0648\\u0631\\u0627\\u0647."
t["Something is eating at these plants."] = "\\u0641\\u064A \\u0634\\u064A \\u0639\\u0645 \\u064A\\u0627\\u0643\\u0644 \\u0647\\u0627\\u0644\\u0632\\u0631\\u0639."
t["Something is pulling hard down there."] = "\\u0641\\u064A \\u0634\\u064A \\u0639\\u0645 \\u064A\\u0634\\u062F \\u0628\\u0642\\u0648\\u0629 \\u062A\\u062D\\u062A."
t["Something is wrong with me. It could be the Knox infection."] = "\\u0641\\u064A \\u0634\\u064A \\u0645\\u0648 \\u0637\\u0628\\u064A\\u0639\\u064A \\u0641\\u064A\\u064A. \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0643\\u0648\\u0646 \\u0639\\u062F\\u0648\\u0649 \\u0646\\u0648\\u0643\\u0633."
t["Something's close, but I don't have eyes on it."] = "\\u0641\\u064A \\u0634\\u064A \\u0642\\u0631\\u064A\\u0628, \\u0628\\u0633 \\u0645\\u0648 \\u0634\\u0627\\u064A\\u0641\\u062A\\u0647."
t["Something's coming through a door. It isn't knocking."] = "\\u0641\\u064A \\u0634\\u064A \\u0639\\u0645 \\u064A\\u062F\\u062E\\u0644 \\u0645\\u0646 \\u0628\\u0627\\u0628. \\u0648\\u0645\\u0627 \\u0639\\u0645 \\u064A\\u062F\\u0642."
t["Something's moving on the other side. Walker, I think."] = "\\u0641\\u064A \\u0634\\u064A \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643 \\u0645\\u0646 \\u0627\\u0644\\u062C\\u0647\\u0629 \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A\\u0629. \\u0634\\u0643\\u0644\\u0647 \\u0632\\u0648\\u0645\\u0628\\u064A."
t["Something's off. I need a second before I fight."] = "\\u0641\\u064A \\u0634\\u064A \\u0645\\u0648 \\u0645\\u0638\\u0628\\u0648\\u0637. \\u0628\\u062F\\u064A \\u0644\\u062D\\u0638\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0642\\u0627\\u062A\\u0644."
t["Something's right there. I can't see it."] = "\\u0641\\u064A \\u0634\\u064A \\u0647\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637. \\u0645\\u0648 \\u0634\\u0627\\u064A\\u0641\\u062A\\u0647."
t["Sometimes I plan a garden in my head. Rows and rows."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062E\\u0637\\u0637 \\u0644\\u062C\\u0646\\u064A\\u0646\\u0629 \\u0628\\u0631\\u0627\\u0633\\u064A. \\u062E\\u0637\\u0648\\u0637 \\u0648\\u062E\\u0637\\u0648\\u0637."
t["Sometimes I set out an extra plate without meaning to."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062D\\u0637 \\u0635\\u062D\\u0646 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0642\\u0635\\u062F."
t["Sometimes I talk to the people we couldn't save. They don't answer."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062D\\u0643\\u064A \\u0645\\u0639 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0627 \\u0642\\u062F\\u0631\\u0646\\u0627 \\u0646\\u0646\\u0642\\u0630\\u0647\\u0645. \\u0645\\u0627 \\u0628\\u064A\\u0631\\u062F\\u0648\\u0627."
t["Sometimes I want to open the gate and shout come on, then."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0641\\u062A\\u062D \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629 \\u0648\\u0627\\u0635\\u0631\\u062E \\u064A\\u0644\\u0627 \\u062A\\u0639\\u0627\\u0644\\u0648\\u0627."
t["Sometimes I want to open the gate and shout come on, you bastards."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0641\\u062A\\u062D \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629 \\u0648\\u0627\\u0635\\u0631\\u062E \\u062A\\u0639\\u0627\\u0644\\u0648\\u0627 \\u064A\\u0627 \\u0648\\u0644\\u0627\\u062F \\u0627\\u0644\\u0643\\u0644\\u0628."
t["Sometimes I want to shout my name at the whole county."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0635\\u0631\\u062E \\u0627\\u0633\\u0645\\u064A \\u0628\\u0648\\u062C\\u0647 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0644\\u0647\\u0627."
t["Sometimes I want to shout my name at the whole damn county."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0635\\u0631\\u062E \\u0627\\u0633\\u0645\\u064A \\u0628\\u0648\\u062C\\u0647 \\u0647\\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629 \\u0643\\u0644\\u0647\\u0627."
t["Sometimes I want to stop running just to see what happens. I don't."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u062F\\u064A \\u0648\\u0642\\u0641 \\u0647\\u0631\\u0628 \\u0628\\u0633 \\u0644\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0628\\u064A\\u0635\\u064A\\u0631. \\u0648\\u0645\\u0627 \\u0628\\u0639\\u0645\\u0644\\u0647\\u0627."
t["Sometimes I wave at windows. In case someone's still home."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u0633\\u0644\\u0651\\u0645 \\u0639\\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643. \\u064A\\u0645\\u0643\\u0646 \\u062D\\u062F\\u0627 \\u0644\\u0633\\u0627 \\u0628\\u0627\\u0644\\u0628\\u064A\\u062A."
t["Sometimes I wonder which of us goes first. Don't look at me."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u0633\\u0623\\u0644 \\u0645\\u064A\\u0646 \\u0641\\u064A\\u0646\\u0627 \\u0623\\u0648\\u0644 \\u0648\\u0627\\u062D\\u062F. \\u0644\\u0627 \\u062A\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u064A."
t["Sometimes I wonder who'll walk these roads after us."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0628\\u0633\\u0623\\u0644 \\u062D\\u0627\\u0644\\u064A \\u0645\\u064A\\u0646 \\u0631\\u062D \\u064A\\u0645\\u0634\\u064A \\u0647\\u0627\\u0644\\u0637\\u0631\\u0642 \\u0628\\u0639\\u062F\\u0646\\u0627."
t["Sometimes the quiet sounds like the world holding its breath."] = "\\u0623\\u062D\\u064A\\u0627\\u0646\\u064B\\u0627 \\u0627\\u0644\\u0633\\u0643\\u0648\\u062A \\u0628\\u064A\\u0635\\u064A\\u0631 \\u0643\\u0623\\u0646 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062D\\u0627\\u0628\\u0633\\u0629 \\u0646\\u0641\\u0633\\u0647\\u0627."
t["Somewhere a bluegrass band is still in tune. Nobody to hear it."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0641\\u0631\\u0642\\u0629 \\u0628\\u0644\\u0648\\u063A\\u0631\\u0627\\u0633 \\u0644\\u0633\\u0627 \\u0645\\u062F\\u0648\\u0632\\u0646\\u0629. \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0633\\u0645\\u0639."
t["Somewhere a preacher is still telling corpses to repent. Good fucking luck."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0642\\u0633\\u064A\\u0633 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u064A\\u0642\\u0648\\u0644 \\u0644\\u0644\\u062C\\u062B\\u062B \\u062A\\u0648\\u0628\\u0648\\u0627. \\u064A\\u0644\\u0627 \\u0628\\u0627\\u0644\\u062A\\u0648\\u0641\\u064A\\u0642\\u060C \\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629."
t["Somewhere a preacher is still telling corpses to repent. Good luck with that."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0642\\u0633\\u064A\\u0633 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u064A\\u0642\\u0648\\u0644 \\u0644\\u0644\\u062C\\u062B\\u062B \\u062A\\u0648\\u0628\\u0648\\u0627. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u0639\\u064A\\u0646\\u0647."
t["Somewhere a speed trap is still waiting for a speeder."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0631\\u0627\\u062F\\u0627\\u0631 \\u0644\\u0633\\u0627 \\u0645\\u0633\\u062A\\u0646\\u064A \\u062D\\u062F\\u0627 \\u0645\\u0633\\u0631\\u0639."
t["Somewhere a therapist just sat up in bed."] = "\\u0628\\u0634\\u064A \\u0645\\u0637\\u0631\\u062D\\u060C \\u062F\\u0643\\u062A\\u0648\\u0631 \\u0646\\u0641\\u0633\\u064A \\u0642\\u0639\\u062F \\u0628\\u062A\\u062E\\u062A\\u0647 \\u0645\\u062E\\u0636\\u0648\\u0636 \\u0647\\u0644\\u0623."
t["Somewhere along the way, this stopped being a deal."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0639\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u060C \\u0628\\u0637\\u0651\\u0644\\u062A \\u0627\\u0644\\u0642\\u0635\\u0629 \\u062A\\u0643\\u0648\\u0646 \\u0635\\u0641\\u0642\\u0629."
t["Somewhere beyond those pines is a working faucet. Maybe."] = "\\u0628\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0627 \\u0648\\u0631\\u0627 \\u0647\\u0627\\u0644\\u0635\\u0646\\u0648\\u0628\\u0631 \\u0641\\u064A \\u062D\\u0646\\u0641\\u064A\\u0629 \\u0634\\u063A\\u0627\\u0644\\u0629. \\u064A\\u0645\\u0643\\u0646."
t["Somewhere in here a mascot costume is still smiling."] = "\\u0641\\u064A \\u0634\\u064A \\u0632\\u0627\\u0648\\u064A\\u0629 \\u0647\\u0648\\u0646 \\u0628\\u062F\\u0644\\u0629 \\u0627\\u0644\\u062F\\u0645\\u064A\\u0629 \\u062A\\u0628\\u0639 \\u0627\\u0644\\u0645\\u0637\\u0639\\u0645 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062A\\u0636\\u062D\\u0643."
t["Somewhere out there's a town with the lights on. I'd bet my boots."] = "\\u0641\\u064A \\u0628\\u0644\\u062F\\u0629 \\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0636\\u0648\\u0627\\u064A\\u0647\\u0627 \\u0634\\u0627\\u0639\\u0644\\u0629. \\u0628\\u0631\\u0627\\u0647\\u0646 \\u0628\\u062C\\u0632\\u0645\\u062A\\u064A."
t["Somewhere safe and quiet. That is what I need."] = "\\u0634\\u064A \\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646 \\u0648\\u0647\\u0627\\u062F\\u064A. \\u0647\\u0627\\u062F \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u064A \\u064A\\u0627\\u0647."
t["Somewhere there is a room with a red ON AIR light."] = "\\u0628\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0627 \\u0641\\u064A \\u063A\\u0631\\u0641\\u0629 \\u0641\\u064A\\u0647\\u0627 \\u0644\\u0645\\u0628\\u0629 \\u062D\\u0645\\u0631\\u0627 \\u0645\\u0643\\u062A\\u0648\\u0628 \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0647\\u0648\\u0627."
t["Somewhere there's a Derby pie with my name on it. Expired."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0641\\u0637\\u064A\\u0631\\u0629 \\u062F\\u064A\\u0631\\u0628\\u064A \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0627\\u0633\\u0645\\u064A. \\u0645\\u0646\\u062A\\u0647\\u064A\\u0629."
t["Somewhere there's a version of me that didn't make it. Lucky?"] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0646\\u0633\\u062E\\u0629 \\u0645\\u0646\\u064A \\u0645\\u0627 \\u0639\\u0627\\u0634\\u062A. \\u0645\\u062D\\u0638\\u0648\\u0638\\u0629\\u061F"
t["Somewhere there's a winning lottery ticket nobody will cash."] = "\\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0648\\u0631\\u0642\\u0629 \\u064A\\u0627\\u0646\\u0635\\u064A\\u0628 \\u0631\\u0627\\u0628\\u062D\\u0629 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0642\\u0628\\u0636\\u0647\\u0627."
t["Soon I won't know why you matter. Right now, you do."] = "\\u0642\\u0631\\u064A\\u0628\\u0627 \\u0645\\u0627 \\u0631\\u062D \\u0627\\u0639\\u0631\\u0641 \\u0644\\u064A\\u0634 \\u0625\\u0646\\u062A \\u0645\\u0647\\u0645. \\u0647\\u0644\\u0623 \\u0628\\u0639\\u0631\\u0641."
t["Sorry, %1. Can I squeeze past?"] = "\\u0639\\u0641\\u0648\\u0627\\u064B \\u064A\\u0627 %1. \\u0641\\u064A\\u0646\\u064A \\u0627\\u0646\\u062D\\u0634\\u0631 \\u062C\\u0646\\u0628\\u0643\\u061F"
t["Sorry, buddy. Heck of a way to go. Heck of a way to stay."] = "\\u0633\\u0627\\u0645\\u062D\\u0646\\u064A \\u064A\\u0627 \\u0635\\u0627\\u062D\\u0628\\u064A. \\u0634\\u0648 \\u0647\\u0627\\u0644\\u0645\\u0648\\u062A\\u0629. \\u0648\\u0634\\u0648 \\u0647\\u0627\\u0644\\u0628\\u0642\\u0627\\u0621."
t["Sorry, buddy. Hell of a way to go. Hell of a way to stay."] = "\\u0633\\u0627\\u0645\\u062D\\u0646\\u064A \\u064A\\u0627 \\u0635\\u0627\\u062D\\u0628\\u064A. \\u064A\\u0644\\u0639\\u0646 \\u0647\\u064A\\u0643 \\u0645\\u0648\\u062A\\u0629. \\u0648\\u064A\\u0644\\u0639\\u0646 \\u0647\\u064A\\u0643 \\u0628\\u0642\\u0627\\u0621."
t["Sorry, hydrant. The fire trucks aren't coming."] = "\\u0622\\u0633\\u0641\\u0629 \\u064A\\u0627 \\u062D\\u0646\\u0641\\u064A\\u0629. \\u0633\\u064A\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u0625\\u0637\\u0641\\u0627\\u0621 \\u0645\\u0648 \\u062C\\u0627\\u064A\\u0629."
t["Sorry, little fellow. Wrong side of the garden."] = "\\u0622\\u0633\\u0641\\u0629 \\u064A\\u0627 \\u0632\\u063A\\u064A\\u0631. \\u063A\\u0644\\u0637 \\u062C\\u0647\\u0629 \\u0628\\u0627\\u0644\\u062C\\u0646\\u064A\\u0646\\u0629."
t["Sorry, neighbor. Nothing personal!"] = "\\u0622\\u0633\\u0641\\u0629 \\u064A\\u0627 \\u062C\\u0627\\u0631. \\u0645\\u0648 \\u0634\\u062E\\u0635\\u064A!"
t["Sorry. I know we have bigger problems. I just need a smoke."] = "\\u0622\\u0633\\u0641\\u0629. \\u0628\\u0639\\u0631\\u0641 \\u0639\\u0646\\u0627 \\u0645\\u0635\\u0627\\u064A\\u0628 \\u0623\\u0643\\u0628\\u0631. \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0633\\u064A\\u062C\\u0627\\u0631\\u0629."
t["Sorry. I thought that was dinner."] = "\\u0622\\u0633\\u0641\\u0629. \\u0641\\u0643\\u0631\\u062A\\u0647 \\u0627\\u0644\\u0639\\u0634\\u0627."
t["Sound travels further than you'd think out here."] = "\\u0627\\u0644\\u0635\\u0648\\u062A \\u0628\\u064A\\u0648\\u0635\\u0644 \\u0647\\u0648\\u0646 \\u0623\\u0628\\u0639\\u062F \\u0645\\u0645\\u0627 \\u0628\\u062A\\u0641\\u0643\\u0631."
t["Soup without bowls is just a transportation problem."] = "\\u0627\\u0644\\u0634\\u0648\\u0631\\u0628\\u0629 \\u0628\\u0644\\u0627 \\u0632\\u0628\\u0627\\u062F\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0646\\u0642\\u0644\\u060C \\u0645\\u0648 \\u0623\\u0643\\u062A\\u0631."
t["Sowing at a useful spacing."] = "\\u0639\\u0645 \\u0627\\u0632\\u0631\\u0639 \\u0628\\u0645\\u0633\\u0627\\u0641\\u0627\\u062A \\u0645\\u0638\\u0628\\u0648\\u0637\\u0629."
t["Spacing these out. We cannot afford to waste them."] = "\\u0639\\u0645 \\u0628\\u0627\\u0639\\u062F \\u0628\\u064A\\u0646\\u0627\\u062A\\u0647\\u0646. \\u0645\\u0627 \\u0645\\u0646\\u0642\\u062F\\u0631 \\u0646\\u0636\\u064A\\u0651\\u0639 \\u0648\\u0644\\u0627 \\u0648\\u062D\\u062F\\u0629."
t["Spare parts don't care how bad the world gets. They still don't fit."] = "\\u0642\\u0637\\u0639 \\u0627\\u0644\\u063A\\u064A\\u0627\\u0631 \\u0645\\u0627 \\u0628\\u064A\\u0647\\u0645\\u0647\\u0627 \\u0642\\u062F\\u064A\\u0634 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062E\\u0631\\u0628\\u0627\\u0646\\u0629. \\u0648\\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0628\\u062A\\u0631\\u0643\\u0628."
t["Spiffo's still smiling. Somebody should stop him."] = "\\u0633\\u0628\\u064A\\u0641\\u0648 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u064A\\u0636\\u062D\\u0643. \\u0644\\u0627\\u0632\\u0645 \\u062D\\u062F\\u0627 \\u064A\\u0648\\u0642\\u0641\\u0647."
t["Spiffo's. Every meal came with a free existential crisis."] = "\\u0633\\u0628\\u064A\\u0641\\u0648. \\u0643\\u0644 \\u0648\\u062C\\u0628\\u0629 \\u0645\\u0639\\u0647\\u0627 \\u0623\\u0632\\u0645\\u0629 \\u0648\\u062C\\u0648\\u062F\\u064A\\u0629 \\u0628\\u0628\\u0644\\u0627\\u0634."
t["Squad's back, headcount matches. Report when you're ready."] = "\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0631\\u062C\\u0639\\u062A\\u060C \\u0648\\u0627\\u0644\\u0639\\u062F\\u062F \\u0645\\u0638\\u0628\\u0648\\u0637. \\u062E\\u0628\\u0631 \\u0644\\u0645\\u0627 \\u062A\\u0643\\u0648\\u0646 \\u062C\\u0627\\u0647\\u0632."
t["Squad, to me! I've got company!"] = "\\u064A\\u0627 \\u062C\\u0645\\u0627\\u0639\\u0629\\u060C \\u0644\\u0639\\u0646\\u062F\\u064A! \\u0639\\u0646\\u062F\\u064A \\u0636\\u064A\\u0648\\u0641!"
t["Stand up when I can't, %1."] = "\\u0642\\u0648\\u0645 \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0623\\u0646\\u0627 \\u064A\\u0627 %1."
t["Standing around is making this worse."] = "\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0628\\u0644\\u0627 \\u0634\\u063A\\u0644 \\u0639\\u0645 \\u062A\\u0632\\u064A\\u062F\\u0647\\u0627."
t["Standing still gives every nearby walker time to make a plan."] = "\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0628\\u062A\\u0639\\u0637\\u064A \\u0643\\u0644 \\u0645\\u064A\\u062A \\u0642\\u0631\\u064A\\u0628 \\u0648\\u0642\\u062A \\u064A\\u062E\\u0637\\u0637."
t["Standing still makes me itch. Point me at something."] = "\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0628\\u062A\\u062D\\u0643\\u0651\\u0646\\u064A. \\u062F\\u0644\\u0651\\u0646\\u064A \\u0639\\u0644\\u0649 \\u0634\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644\\u0647."
t["Starting on the plot now."] = "\\u0639\\u0645 \\u0627\\u0628\\u0644\\u0651\\u0634 \\u0628\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0647\\u0644\\u0623."
t["State your business from there."] = "\\u0642\\u0648\\u0644 \\u0634\\u0648 \\u0628\\u062F\\u0643 \\u0645\\u0646 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["State your business. We can manage that without opening the house."] = "\\u0642\\u0648\\u0644 \\u0634\\u0648 \\u0628\\u062F\\u0643. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0646\\u0641\\u062A\\u062D \\u0627\\u0644\\u0628\\u064A\\u062A."
t["Static sounds like snow falling on an empty highway."] = "\\u0627\\u0644\\u062A\\u0634\\u0648\\u064A\\u0634 \\u0635\\u0648\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u062A\\u0644\\u062C \\u0646\\u0627\\u0632\\u0644 \\u0639\\u0644\\u0649 \\u0623\\u0648\\u062A\\u0648\\u0633\\u062A\\u0631\\u0627\\u062F \\u0641\\u0627\\u0636\\u064A."
t["Stay alive - but please, try to reach me!"] = "\\u0636\\u0644 \\u0639\\u0627\\u064A\\u0634 - \\u0628\\u0633 \\u062D\\u0627\\u0648\\u0644 \\u062A\\u0648\\u0635\\u0644\\u064A!"
t["Stay at the entry. You're welcome to a conversation."] = "\\u062E\\u0644\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0645\\u062F\\u062E\\u0644. \\u0627\\u0644\\u062D\\u0643\\u064A \\u0623\\u0647\\u0644\\u0627 \\u0648\\u0633\\u0647\\u0644\\u0627 \\u0641\\u064A\\u0647."
t["Stay at the gate. We cannot risk spreading this."] = "\\u062E\\u0644\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629. \\u0645\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0627\\u0637\\u0631 \\u0625\\u0646\\u0647 \\u064A\\u0646\\u062A\\u0634\\u0631."
t["Stay away. This house is occupied."] = "\\u0627\\u0628\\u0639\\u062F. \\u0647\\u0627\\u0644\\u0628\\u064A\\u062A \\u0641\\u064A \\u0646\\u0627\\u0633 \\u0633\\u0627\\u0643\\u0646\\u064A\\u0646 \\u0641\\u064A\\u0647."
t["Stay back, please. We're trying to keep people alive here."] = "\\u0627\\u0628\\u0639\\u062F\\u060C \\u0644\\u0648 \\u0633\\u0645\\u062D\\u062A. \\u0639\\u0645 \\u0646\\u062D\\u0627\\u0648\\u0644 \\u0646\\u062E\\u0644\\u064A \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0639\\u0627\\u064A\\u0634\\u0629 \\u0647\\u0648\\u0646."
t["Stay back. I'll take this one."] = "\\u0627\\u0628\\u0639\\u062F. \\u0647\\u0627\\u062F \\u0639\\u0646\\u062F\\u064A."
t["Stay behind me!"] = "\\u062E\\u0644\\u064A\\u0643 \\u0648\\u0631\\u0627\\u064A\\u064A!"
t["Stay close in this fog. I don't want to lose sight of you."] = "\\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628 \\u0628\\u0647\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0636\\u064A\\u0639\\u0643."
t["Stay close until it's done. Please."] = "\\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628 \\u0644\\u062A\\u062E\\u0644\\u0635. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["Stay close, %1. I want to leave this world beside my family."] = "\\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628 \\u064A\\u0627 %1. \\u0628\\u062F\\u064A \\u0641\\u0644 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062C\\u0646\\u0628 \\u0639\\u064A\\u0644\\u062A\\u064A."
t["Stay close. I heard one nearby."] = "\\u062E\\u0644\\u064A\\u0643 \\u062C\\u0646\\u0628\\u064A. \\u0633\\u0645\\u0639\\u062A \\u0648\\u0627\\u062D\\u062F \\u0642\\u0631\\u064A\\u0628."
t["Stay close. This place makes me worry about all of us."] = "\\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628. \\u0647\\u0627\\u0644\\u0645\\u0637\\u0631\\u062D \\u0645\\u062E\\u0644\\u064A\\u0646\\u064A \\u062E\\u0627\\u064A\\u0641\\u0629 \\u0639\\u0644\\u064A\\u0646\\u0627 \\u0643\\u0644\\u0646\\u0627."
t["Stay close. We can make this a good day together."] = "\\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u064A\\u0647 \\u064A\\u0648\\u0645 \\u0645\\u0646\\u064A\\u062D \\u0633\\u0648\\u0627."
t["Stay dead."] = "\\u0636\\u0644 \\u0645\\u064A\\u062A."
t["Stay down and leave me alone!"] = "\\u062E\\u0644\\u064A\\u0643 \\u0648\\u0627\\u0642\\u0639 \\u0648\\u0627\\u062A\\u0631\\u0643\\u0646\\u064A \\u0628\\u062D\\u0627\\u0644\\u064A!"
t["Stay down!"] = "\\u0636\\u0644 \\u0648\\u0627\\u0642\\u0639!"
t["Stay down. I don't want your blood on me."] = "\\u062E\\u0644\\u064A\\u0643 \\u0648\\u0627\\u0642\\u0639. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062F\\u0645\\u0643 \\u0639\\u0644\\u064A\\u0651."
t["Stay off rotten porches. Worse things wait behind the doors."] = "\\u0627\\u0628\\u0639\\u062F \\u0639\\u0646 \\u0627\\u0644\\u0628\\u0631\\u0646\\u062F\\u0627\\u062A \\u0627\\u0644\\u0645\\u0647\\u062A\\u0631\\u064A\\u0629. \\u0648\\u0631\\u0627 \\u0623\\u0628\\u0648\\u0627\\u0628\\u0647\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0623\\u0639\\u0648\\u0633."
t["Stay on me! One line, straight out!"] = "\\u062E\\u0644\\u064A\\u0643 \\u0648\\u0631\\u0627\\u064A\\u064A! \\u062E\\u0637 \\u0648\\u0627\\u062D\\u062F, \\u062F\\u063A\\u0631\\u064A \\u0644\\u0628\\u0631\\u0627!"
t["Stay on this station. I want to hear the rest."] = "\\u0636\\u0644 \\u0639\\u0647\\u0627\\u0644\\u0645\\u062D\\u0637\\u0629. \\u0628\\u062F\\u064A \\u0627\\u0633\\u0645\\u0639 \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A."
t["Stay over there until you calm down."] = "\\u0636\\u0644 \\u0647\\u0648\\u0646\\u064A\\u0643 \\u0644\\u062A\\u0647\\u062F\\u0649."
t["Stay together and run! I'll watch the rear!"] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0633\\u0648\\u0627 \\u0648\\u0627\\u0631\\u0643\\u0636\\u0648\\u0627! \\u0623\\u0646\\u0627 \\u0628\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0627\\u0644\\u0648\\u0631\\u0627!"
t["Stay together! Nobody disappears in that horde!"] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0633\\u0648\\u0627! \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0636\\u064A\\u0639 \\u0628\\u0647\\u0627\\u0644\\u0645\\u0648\\u062C\\u0629!"
t["Stay together! Nobody gets pulled into that group!"] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0633\\u0648\\u0627! \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0646\\u0633\\u062D\\u0628 \\u0644\\u0639\\u0646\\u062F \\u0647\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629!"
t["Stay until it gets quiet. Then keep going."] = "\\u0636\\u0644 \\u0644\\u062D\\u062A\\u0649 \\u064A\\u0647\\u062F\\u0649 \\u0627\\u0644\\u0648\\u0636\\u0639. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0643\\u0645\\u0644."
t["Stay where I can see you, please."] = "\\u062E\\u0644\\u064A\\u0643 \\u0648\\u064A\\u0646 \\u0628\\u0634\\u0648\\u0641\\u0643\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["Stay where you are. I'm done."] = "\\u062E\\u0644\\u064A\\u0643 \\u0645\\u062D\\u0644\\u0643. \\u0623\\u0646\\u0627 \\u062E\\u0644\\u0635\\u062A."
t["Stay with me - no, go! Go!"] = "\\u0636\\u0644 \\u0645\\u0639\\u064A - \\u0644\\u0623, \\u0631\\u0648\\u062D! \\u0631\\u0648\\u062D!"
t["Stay with me a moment. That helps."] = "\\u062E\\u0644\\u064A\\u0643 \\u0645\\u0639\\u064A \\u0634\\u0648\\u064A. \\u0647\\u064A\\u0643 \\u0623\\u062D\\u0633\\u0646."
t["Stay with me! We're getting everyone out!"] = "\\u062E\\u0644\\u064A\\u0643 \\u0645\\u0639\\u064A! \\u0643\\u0644\\u0646\\u0627 \\u0631\\u062D \\u0646\\u0637\\u0644\\u0639!"
t["Stay with me. I'm getting this wrapped."] = "\\u062E\\u0644\\u064A\\u0643 \\u0645\\u0639\\u064A. \\u0639\\u0645 \\u0644\\u0641\\u0651\\u0647\\u0627."
t["Stay with me. Just until I fall asleep. Then go."] = "\\u062E\\u0644\\u064A\\u0643 \\u0645\\u0639\\u064A. \\u0628\\u0633 \\u0644\\u0646\\u0627\\u0645. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0631\\u0648\\u062D."
t["Step around me. I need room to scrub."] = "\\u0644\\u0641 \\u0645\\u0646 \\u062D\\u0648\\u0644\\u064A. \\u0628\\u062F\\u064A \\u0645\\u062D\\u0644 \\u0627\\u0641\\u0631\\u0643."
t["Still %1 at %2. I've got the right place."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1 \\u0639\\u0646\\u062F %2. \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0635\\u062D."
t["Still %1, by another route. The first one had opinions."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1\\u060C \\u0645\\u0646 \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A. \\u0627\\u0644\\u0623\\u0648\\u0644\\u0627\\u0646\\u064A \\u0643\\u0627\\u0646 \\u0625\\u0644\\u0647 \\u0631\\u0623\\u064A."
t["Still %1. Could be worse."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1. \\u0643\\u0627\\u0646 \\u0645\\u0645\\u0643\\u0646 \\u0623\\u0633\\u0648\\u0623."
t["Still %1. I need a clear approach before I continue."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0641\\u0627\\u0636\\u064A\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0643\\u0641\\u0651\\u064A."
t["Still %1. I'm checking a different approach."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1. \\u0639\\u0645 \\u062C\\u0631\\u0628 \\u0637\\u0631\\u064A\\u0642\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Still %1. Nothing has stopped the work."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1. \\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0648\\u0642\\u0651\\u0641 \\u0627\\u0644\\u0634\\u063A\\u0644."
t["Still %1. Rethinking the approach."] = "\\u0644\\u0633\\u0627 \\u0628\\u0640%1. \\u0639\\u0645 \\u0639\\u064A\\u062F \\u0627\\u0644\\u062A\\u0641\\u0643\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u0629."
t["Still busy. That's the whole report."] = "\\u0644\\u0633\\u0627 \\u0645\\u0634\\u063A\\u0648\\u0644\\u0629. \\u0647\\u0627\\u062F \\u0643\\u0644 \\u0627\\u0644\\u062A\\u0642\\u0631\\u064A\\u0631."
t["Still here. That counts for a lot, %1."] = "\\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646. \\u0648\\u0647\\u0627\\u062F \\u0628\\u064A\\u0633\\u0648\\u0649 \\u0643\\u062A\\u064A\\u0631 \\u064A\\u0627 %1."
t["Still made it. That is what matters."] = "\\u0627\\u0644\\u0645\\u0647\\u0645 \\u0648\\u0635\\u0644\\u062A. \\u0647\\u0627\\u062F \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0647\\u0645."
t["Still moving. I will need rest later."] = "\\u0644\\u0633\\u0627 \\u0645\\u0627\\u0634\\u064A\\u0629. \\u0631\\u062D \\u0627\\u062D\\u062A\\u0627\\u062C \\u0631\\u0627\\u062D\\u0629 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["Still smells like fry oil. The last good smell in Knox County."] = "\\u0644\\u0633\\u0627 \\u0631\\u064A\\u062D\\u062A\\u0647 \\u0632\\u064A\\u062A \\u0642\\u0644\\u064A. \\u0622\\u062E\\u0631 \\u0631\\u064A\\u062D\\u0629 \\u062D\\u0644\\u0648\\u0629 \\u0628\\u0646\\u0648\\u0643\\u0633."
t["Still upright. That's the whole report."] = "\\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641\\u0629. \\u0647\\u0627\\u062F \\u0643\\u0644 \\u0627\\u0644\\u062A\\u0642\\u0631\\u064A\\u0631."
t["Still waiting to finish %1. It seems committed to taking its time."] = "\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0627\\u0633\\u062A\\u0646\\u0649 \\u0644\\u062E\\u0644\\u0651\\u0635 %1. \\u0627\\u0644\\u0638\\u0627\\u0647\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631 \\u0645\\u0648 \\u0645\\u0633\\u062A\\u0639\\u062C\\u0644\\u0629 \\u0623\\u0628\\u062F\\u0627\\u064B."
t["Still waiting. Fine. Not good. Fine."] = "\\u0644\\u0633\\u0627 \\u0645\\u0633\\u062A\\u0646\\u064A\\u0629. \\u062A\\u0645\\u0627\\u0645. \\u0645\\u0648 \\u062A\\u0645\\u0627\\u0645. \\u062A\\u0645\\u0627\\u0645."
t["Still with you. Long road ahead."] = "\\u0644\\u0633\\u0627 \\u0645\\u0639\\u0643. \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0637\\u0648\\u064A\\u0644."
t["Stop at the boundary and tell us what you want."] = "\\u0648\\u0642\\u0641 \\u0639\\u0627\\u0644\\u062D\\u062F \\u0648\\u0642\\u0644\\u0646\\u0627 \\u0634\\u0648 \\u0628\\u062F\\u0643."
t["Stop blaming me for every bad call."] = "\\u0628\\u0637\\u0651\\u0644 \\u062A\\u0644\\u0648\\u0645\\u0646\\u064A \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0642\\u0631\\u0627\\u0631 \\u0639\\u0627\\u0637\\u0644."
t["Stop right there."] = "\\u0648\\u0642\\u0641 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["Stop right there. Next swing, I defend myself."] = "\\u0648\\u0642\\u0641 \\u0645\\u062D\\u0644\\u0643. \\u0627\\u0644\\u0636\\u0631\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u062F\\u0627\\u0641\\u0639 \\u0639\\u0646 \\u062D\\u0627\\u0644\\u064A."
t["Stop right there. Turn around."] = "\\u0648\\u0642\\u0641 \\u0645\\u0637\\u0631\\u062D\\u0643. \\u0644\\u0641 \\u0648\\u0627\\u0631\\u062C\\u0639."
t["Stop there. We can hear you without opening anything."] = "\\u0648\\u0642\\u0641 \\u0639\\u0646\\u062F\\u0643. \\u0633\\u0627\\u0645\\u0639\\u064A\\u0646\\u0643 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0646\\u0641\\u062A\\u062D \\u0634\\u064A."
t["Stop there. We don't trust strangers."] = "\\u0648\\u0642\\u0641 \\u0639\\u0646\\u062F\\u0643. \\u0646\\u062D\\u0646\\u0627 \\u0645\\u0627 \\u0645\\u0646\\u0648\\u062B\\u0642 \\u0628\\u0627\\u0644\\u063A\\u0631\\u0628\\u0627."
t["Stop. I am going to collapse if I keep moving."] = "\\u0648\\u0642\\u0627\\u0641. \\u0631\\u062D \\u0627\\u0648\\u0642\\u0639 \\u0625\\u0630\\u0627 \\u0636\\u0644\\u064A\\u062A \\u0645\\u0627\\u0634\\u064A\\u0629."
t["Stop. I am too hungry to be safe out here."] = "\\u0648\\u0642\\u0627\\u0641. \\u062C\\u0648\\u0639\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u0623\\u0643\\u0648\\u0646 \\u0628\\u0623\\u0645\\u0627\\u0646 \\u0647\\u0648\\u0646."
t["Stop. I need something safe to drink."] = "\\u0648\\u0642\\u0627\\u0641. \\u0628\\u062F\\u064A \\u0634\\u064A \\u0622\\u0645\\u0646 \\u0627\\u0634\\u0631\\u0628\\u0647."
t["Stop. This has gone far enough."] = "\\u0648\\u0642\\u0641. \\u0648\\u0635\\u0644\\u062A \\u0644\\u0622\\u062E\\u0631\\u0647\\u0627."
t["Storage, defenses, routines. The system is working."] = "\\u0645\\u0648\\u0646\\u0629\\u060C \\u062A\\u062D\\u0635\\u064A\\u0646\\u060C \\u0648\\u062A\\u0631\\u062A\\u064A\\u0628 \\u064A\\u0648\\u0645\\u064A. \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631 \\u0645\\u0627\\u0634\\u064A\\u0629 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629."
t["Straight answer:"] = "\\u062C\\u0648\\u0627\\u0628 \\u062F\\u063A\\u0631\\u064A:"
t["Strange seeing ordinary life still running on that screen."] = "\\u063A\\u0631\\u064A\\u0628 \\u062A\\u0634\\u0648\\u0641 \\u0627\\u0644\\u062D\\u064A\\u0627\\u0629 \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A\\u0629 \\u0644\\u0633\\u0627 \\u0645\\u0627\\u0634\\u064A\\u0629 \\u0639\\u0647\\u0627\\u0644\\u0634\\u0627\\u0634\\u0629."
t["Strategic Kentucky reserve. National morale is apparently in barrels."] = "\\u0627\\u062D\\u062A\\u064A\\u0627\\u0637\\u064A \\u0643\\u0646\\u062A\\u0627\\u0643\\u064A \\u0627\\u0644\\u0627\\u0633\\u062A\\u0631\\u0627\\u062A\\u064A\\u062C\\u064A. \\u0627\\u0644\\u0645\\u0639\\u0646\\u0648\\u064A\\u0627\\u062A \\u0627\\u0644\\u0648\\u0637\\u0646\\u064A\\u0629 \\u0637\\u0644\\u0639\\u062A \\u0628\\u0628\\u0631\\u0627\\u0645\\u064A\\u0644."
t["Strike. Spare. Everybody else."] = "\\u0633\\u062A\\u0631\\u0627\\u064A\\u0643. \\u0633\\u0628\\u064A\\u0631. \\u0648\\u0643\\u0644 \\u0627\\u0644\\u0628\\u0642\\u064A\\u0629."
t["Strong feeling I've said this before. Have I said this before?"] = "\\u062D\\u0627\\u0633\\u0629 \\u0625\\u0646\\u064A \\u0642\\u0644\\u062A \\u0647\\u0627\\u0644\\u0634\\u064A \\u0642\\u0628\\u0644. \\u0642\\u0644\\u062A \\u0647\\u0627\\u0644\\u0634\\u064A \\u0642\\u0628\\u0644\\u061F"
t["Strong feeling we've had this exact evening before."] = "\\u062D\\u0627\\u0633\\u0629 \\u0625\\u0646\\u0627 \\u0639\\u0634\\u0646\\u0627 \\u0647\\u0627\\u0644\\u0645\\u0633\\u0627 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637 \\u0642\\u0628\\u0644."
t["Strong urge to ring a dinner bell. We don't have a damn dinner bell."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u062F\\u0642 \\u062C\\u0631\\u0633 \\u0627\\u0644\\u0639\\u0634\\u0627. \\u0645\\u0627 \\u0639\\u0646\\u0627 \\u062C\\u0631\\u0633 \\u0639\\u0634\\u0627 \\u064A\\u0644\\u0639\\u0646."
t["Strong urge to ring a dinner bell. We don't have a dinner bell."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u062F\\u0642 \\u062C\\u0631\\u0633 \\u0627\\u0644\\u0639\\u0634\\u0627. \\u0645\\u0627 \\u0639\\u0646\\u0627 \\u062C\\u0631\\u0633 \\u0639\\u0634\\u0627."
t["Strong urge to ring every doorbell in this county. Ignoring it."] = "\\u0639\\u0646\\u062F\\u064A \\u0631\\u063A\\u0628\\u0629 \\u0627\\u062F\\u0642 \\u0643\\u0644 \\u062C\\u0631\\u0633 \\u0628\\u064A\\u062A \\u0628\\u0647\\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629. \\u0639\\u0645 \\u0637\\u0646\\u0651\\u0634."
t["Strong urge to ring every goddamn doorbell in this county. Ignoring it."] = "\\u0639\\u0646\\u062F\\u064A \\u0631\\u063A\\u0628\\u0629 \\u0627\\u062F\\u0642 \\u0643\\u0644 \\u062C\\u0631\\u0633 \\u0628\\u064A\\u062A \\u0628\\u0647\\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u064A\\u0644\\u0639\\u0646\\u0647\\u0627. \\u0639\\u0645 \\u0637\\u0646\\u0651\\u0634."
t["Sudden urge to sweep the whole place at midnight."] = "\\u0631\\u063A\\u0628\\u0629 \\u0645\\u0641\\u0627\\u062C\\u0626\\u0629 \\u0627\\u0643\\u0646\\u0633 \\u0643\\u0644 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0646\\u0635 \\u0627\\u0644\\u0644\\u064A\\u0644."
t["Sun's down soon. I'll check that we're ready for the night."] = "\\u0627\\u0644\\u0634\\u0645\\u0633 \\u0642\\u0631\\u0628\\u062A \\u062A\\u063A\\u064A\\u0628. \\u0628\\u0634\\u064A\\u0643 \\u0625\\u0630\\u0627 \\u062C\\u0627\\u0647\\u0632\\u064A\\u0646 \\u0644\\u0644\\u064A\\u0644."
t["Sun's getting low. We should check our way back."] = "\\u0627\\u0644\\u0634\\u0645\\u0633 \\u0639\\u0645 \\u062A\\u0646\\u0632\\u0644. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0634\\u064A\\u0643 \\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0631\\u062C\\u0639\\u0629."
t["Sunday meant dishes in the sink and nowhere urgent to be."] = "\\u0627\\u0644\\u0623\\u062D\\u062F \\u064A\\u0639\\u0646\\u064A \\u0635\\u062D\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0645\\u062C\\u0644\\u0649 \\u0648\\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0645\\u0633\\u062A\\u0639\\u062C\\u0644."
t["Supplies are counted and the place is standing. How are you, %1?"] = "\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0645\\u0639\\u062F\\u0648\\u062F\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0637\\u0631\\u062D \\u0648\\u0627\\u0642\\u0641. \\u0643\\u064A\\u0641\\u0643 \\u064A\\u0627 %1\\u061F"
t["Surrounded? Heck no. I'm making an exit."] = "\\u0645\\u062D\\u0627\\u0635\\u0631\\u0629\\u061F \\u0644\\u0623 \\u0648\\u0623\\u0644\\u0641 \\u0644\\u0623. \\u0639\\u0645 \\u0627\\u0639\\u0645\\u0644\\u064A \\u0637\\u0644\\u0639\\u0629."
t["Surrounded? Hell no. I'm making an exit."] = "\\u0645\\u062D\\u0627\\u0635\\u0631\\u0629\\u061F \\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627\\u060C \\u0644\\u0623. \\u0639\\u0645 \\u0627\\u0639\\u0645\\u0644\\u064A \\u0637\\u0644\\u0639\\u0629."
t["Suspicious or not, I'll take a cup."] = "\\u0645\\u0634\\u0628\\u0648\\u0647 \\u0648\\u0644\\u0627 \\u0644\\u0623\\u060C \\u0628\\u0634\\u0631\\u0628 \\u0643\\u0627\\u0633\\u0629."
t["Swing your partner! Then swing harder!"] = "\\u064A\\u0644\\u0627 \\u062F\\u0628\\u0643\\u0629! \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0627\\u0644\\u0631\\u0627\\u0633 \\u0648\\u0628\\u0636\\u0631\\u0628 \\u0623\\u0642\\u0648\\u0649!"
t["Tab's still open. I'm not paying it."] = "\\u0627\\u0644\\u062D\\u0633\\u0627\\u0628 \\u0644\\u0633\\u0627 \\u0645\\u0641\\u062A\\u0648\\u062D. \\u0623\\u0646\\u0627 \\u0645\\u0648 \\u062F\\u0627\\u0641\\u0639\\u0629."
t["Tags on the toes. We used to be so organized."] = "\\u0628\\u0637\\u0627\\u0642\\u0627\\u062A \\u0639\\u0627\\u0644\\u0623\\u0635\\u0627\\u0628\\u0639. \\u0643\\u0646\\u0627 \\u0645\\u0646\\u0638\\u0645\\u064A\\u0646 \\u0643\\u062A\\u064A\\u0631."
t["Take a breath. Put the weapon down."] = "\\u062E\\u0648\\u062F \\u0646\\u0641\\u0633. \\u0646\\u0632\\u0651\\u0644 \\u0627\\u0644\\u0633\\u0644\\u0627\\u062D."
t["Take a breather first, then we'll see what needs doing."] = "\\u062E\\u0648\\u062F \\u0646\\u0641\\u0633 \\u0623\\u0648\\u0644\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0644\\u0627\\u0632\\u0645."
t["Take a number. Yours is up!"] = "\\u062E\\u062F \\u0631\\u0642\\u0645. \\u0648\\u0625\\u062C\\u0627 \\u062F\\u0648\\u0631\\u0643!"
t["Take care of them the way you took care of me."] = "\\u0627\\u0647\\u062A\\u0645 \\u0641\\u064A\\u0647\\u0646 \\u0645\\u062A\\u0644 \\u0645\\u0627 \\u0627\\u0647\\u062A\\u0645\\u064A\\u062A \\u0641\\u064A\\u064A."
t["Take care. I mean that."] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643. \\u0639\\u0646 \\u062C\\u062F."
t["Take inventory when this is over. Nothing gets wasted."] = "\\u062C\\u0631\\u062F \\u0627\\u0644\\u063A\\u0631\\u0627\\u0636 \\u0644\\u0645\\u0627 \\u064A\\u062E\\u0644\\u0635 \\u0647\\u0627\\u0644\\u0634\\u064A. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0634\\u064A \\u064A\\u0636\\u064A\\u0639."
t["Take no chances with me, %1. None."] = "\\u0644\\u0627 \\u062A\\u062E\\u0627\\u0637\\u0631 \\u0645\\u0639\\u064A \\u064A\\u0627 %1. \\u0623\\u0628\\u062F\\u0627."
t["Take the cans without dents. We've had enough surprises inside things."] = "\\u062E\\u0648\\u062F \\u0627\\u0644\\u0639\\u0644\\u0628 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0648 \\u0645\\u0637\\u0639\\u0648\\u062C\\u0629. \\u0634\\u0628\\u0639\\u0646\\u0627 \\u0645\\u0641\\u0627\\u062C\\u0622\\u062A \\u062C\\u0648\\u0627 \\u0627\\u0644\\u0623\\u063A\\u0631\\u0627\\u0636."
t["Take the one at my shoulders first!"] = "\\u0623\\u0648\\u0644 \\u0634\\u064A \\u0627\\u0644\\u0644\\u064A \\u0639\\u0646\\u062F \\u0643\\u062A\\u0627\\u0641\\u064A!"
t["Take the south exit if you have to leave quickly."] = "\\u062E\\u062F \\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0627\\u0644\\u0642\\u0628\\u0644\\u064A \\u0625\\u0630\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0641\\u0644 \\u0628\\u0633\\u0631\\u0639\\u0629."
t["Take the things in my bag. I chose them for us."] = "\\u062E\\u062F \\u0627\\u0644\\u0644\\u064A \\u0628\\u0634\\u0646\\u062A\\u062A\\u064A. \\u0646\\u0642\\u064A\\u062A\\u0647 \\u0625\\u0644\\u0646\\u0627."
t["Take the thinnest useful book. Space in a pack matters."] = "\\u062E\\u0648\\u062F \\u0623\\u0631\\u0641\\u0639 \\u0643\\u062A\\u0627\\u0628 \\u0645\\u0641\\u064A\\u062F. \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u0627\\u0644\\u0634\\u0646\\u062A\\u0627\\u064A\\u0629 \\u0628\\u064A\\u0641\\u0631\\u0642."
t["Take your time. The zombies sure are."] = "\\u062E\\u0648\\u062F \\u0648\\u0642\\u062A\\u0643. \\u0627\\u0644\\u0632\\u0648\\u0645\\u0628\\u064A \\u0643\\u0645\\u0627\\u0646 \\u0622\\u062E\\u062F\\u064A\\u0646 \\u0648\\u0642\\u062A\\u0647\\u0645."
t["Taking %1 for the quiet stops, if we get any."] = "\\u0628\\u0627\\u062E\\u062F %1 \\u0644\\u0644\\u0648\\u0642\\u0641\\u0627\\u062A \\u0627\\u0644\\u0647\\u0627\\u062F\\u064A\\u0629\\u060C \\u0625\\u0630\\u0627 \\u0635\\u0627\\u0631 \\u0641\\u064A."
t["Taking %1. Reading time is cheaper than mistakes."] = "\\u0628\\u0627\\u062E\\u062F %1. \\u0627\\u0644\\u0642\\u0631\\u0627\\u0621\\u0629 \\u0623\\u0631\\u062E\\u0635 \\u0645\\u0646 \\u0627\\u0644\\u063A\\u0644\\u0637\\u0627\\u062A."
t["Taking it down!"] = "\\u0631\\u062D \\u0627\\u0648\\u0642\\u0639\\u0647!"
t["Taking the only one in sight!"] = "\\u0639\\u0645 \\u0622\\u062E\\u062F \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F \\u0627\\u0644\\u0645\\u0628\\u064A\\u0646!"
t["Talk to me a moment. Your voice helps me stay here."] = "\\u0627\\u062D\\u0643\\u064A\\u0644\\u064A \\u0634\\u0648\\u064A. \\u0635\\u0648\\u062A\\u0643 \\u0628\\u064A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0647\\u0648\\u0646."
t["Talk to me now and then. Helps me know you're all right."] = "\\u0627\\u062D\\u0643\\u064A\\u0646\\u064A \\u0643\\u0644 \\u0634\\u0648\\u064A. \\u0628\\u0637\\u0645\\u0646 \\u0625\\u0646\\u0643 \\u0645\\u0646\\u064A\\u062D."
t["Talk to me. Tell me what you need."] = "\\u0627\\u062D\\u0643\\u064A\\u0644\\u064A. \\u0642\\u0644\\u064A \\u0634\\u0648 \\u0628\\u062F\\u0643."
t["Target down!"] = "\\u0627\\u0644\\u0647\\u062F\\u0641 \\u0648\\u0642\\u0639!"
t["Target down. Keep watching!"] = "\\u0627\\u0644\\u0647\\u062F\\u0641 \\u0648\\u0642\\u0639. \\u0636\\u0644 \\u0627\\u0646\\u062A\\u0628\\u0647!"
t["Target is still active!"] = "\\u0627\\u0644\\u0647\\u062F\\u0641 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643!"
t["Target neutralized."] = "\\u0627\\u0644\\u0647\\u062F\\u0641 \\u0627\\u0646\\u062A\\u0647\\u0649."
t["Target selected. Engaging!"] = "\\u0646\\u0642\\u064A\\u062A \\u0647\\u062F\\u0641\\u064A. \\u0639\\u0645 \\u0647\\u0627\\u062C\\u0645!"
t["Team, this is a radio check. How's my signal?"] = "\\u064A\\u0627 \\u0634\\u0628\\u0627\\u0628\\u060C \\u0641\\u062D\\u0635 \\u0631\\u0627\\u062F\\u064A\\u0648. \\u0643\\u064A\\u0641 \\u0635\\u0648\\u062A\\u064A\\u061F"
t["Teeth, blood, apocalypse. Somehow the cigarette's what I miss."] = "\\u0633\\u0646\\u0627\\u0646\\u060C \\u062F\\u0645\\u060C \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645. \\u0648\\u0628\\u0627\\u0644\\u0622\\u062E\\u0631 \\u0627\\u0644\\u0633\\u064A\\u062C\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0634\\u062A\\u0627\\u0642\\u062A\\u0644\\u0647\\u0627."
t["Tell everyone my last thought was of home."] = "\\u0642\\u0648\\u0644 \\u0644\\u0644\\u0643\\u0644 \\u0622\\u062E\\u0631 \\u0641\\u0643\\u0631\\u0629 \\u0639\\u0646\\u062F\\u064A \\u0643\\u0627\\u0646\\u062A \\u0627\\u0644\\u0628\\u064A\\u062A."
t["Tell me I'm not disappearing alone."] = "\\u0642\\u0644\\u064A \\u0625\\u0646\\u064A \\u0645\\u0648 \\u0639\\u0645 \\u0627\\u062E\\u062A\\u0641\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A."
t["Tell me about somewhere safe, even if you have to invent it."] = "\\u0627\\u062D\\u0643\\u064A\\u0644\\u064A \\u0639\\u0646 \\u0645\\u0643\\u0627\\u0646 \\u0623\\u0645\\u0627\\u0646, \\u062D\\u062A\\u0649 \\u0644\\u0648 \\u0628\\u062A\\u062E\\u062A\\u0631\\u0639\\u0647."
t["Tell me we mattered. Please."] = "\\u0642\\u0644\\u064A \\u0643\\u0627\\u0646 \\u0625\\u0644\\u0646\\u0627 \\u0642\\u064A\\u0645\\u0629. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["Tell me who I am. Quickly."] = "\\u0642\\u0644\\u064A \\u0645\\u064A\\u0646 \\u0623\\u0646\\u0627. \\u0628\\u0633\\u0631\\u0639\\u0629."
t["Tell me you heard that too."] = "\\u0642\\u0644\\u064A \\u0625\\u0646\\u0643 \\u0633\\u0645\\u0639\\u062A \\u0643\\u0645\\u0627\\u0646."
t["Tell our family I loved them. You already know I loved you."] = "\\u0642\\u0648\\u0644 \\u0644\\u0639\\u064A\\u0644\\u062A\\u0646\\u0627 \\u0625\\u0646\\u064A \\u062D\\u0628\\u064A\\u062A\\u0646. \\u0625\\u0646\\u062A \\u0628\\u062A\\u0639\\u0631\\u0641 \\u0625\\u0646\\u064A \\u062D\\u0628\\u064A\\u062A\\u0643."
t["Tell our family I remembered every one of them at the end."] = "\\u0642\\u0648\\u0644 \\u0644\\u0639\\u064A\\u0644\\u062A\\u0646\\u0627 \\u0625\\u0646\\u064A \\u062A\\u0630\\u0643\\u0631\\u062A\\u0646 \\u0648\\u0627\\u062D\\u062F \\u0648\\u0627\\u062D\\u062F \\u0628\\u0627\\u0644\\u0622\\u062E\\u0631."
t["Tell the fence I won."] = "\\u0642\\u0648\\u0644 \\u0644\\u0644\\u0633\\u0648\\u0631 \\u0625\\u0646\\u064A \\u0631\\u0628\\u062D\\u062A."
t["Tell the others I stayed human to the end."] = "\\u0642\\u0648\\u0644 \\u0644\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646 \\u0636\\u0644\\u064A\\u062A \\u0625\\u0646\\u0633\\u0627\\u0646\\u0629 \\u0644\\u0644\\u0622\\u062E\\u0631."
t["Tell them yourself, or I will. Your choice, but make it now."] = "\\u062E\\u0628\\u0631\\u0647\\u0646 \\u0625\\u0646\\u062A\\u060C \\u0623\\u0648 \\u0623\\u0646\\u0627 \\u0628\\u062E\\u0628\\u0631\\u0647\\u0646. \\u0627\\u0644\\u062E\\u064A\\u0627\\u0631 \\u0625\\u0644\\u0643\\u060C \\u0628\\u0633 \\u0647\\u0644\\u0623."
t["Tell us what you need. Leave out the promises."] = "\\u0642\\u0644\\u0646\\u0627 \\u0634\\u0648 \\u0628\\u062F\\u0643. \\u0648\\u0628\\u0644\\u0627 \\u0648\\u0639\\u0648\\u062F."
t["Temporary evacuation lodging. Checkout time has been generously extended."] = "\\u0633\\u0643\\u0646 \\u0625\\u062E\\u0644\\u0627\\u0621 \\u0645\\u0624\\u0642\\u062A. \\u0648\\u0642\\u062A \\u0627\\u0644\\u0645\\u063A\\u0627\\u062F\\u0631\\u0629 \\u062A\\u0645\\u062F\\u062F \\u0628\\u0643\\u0631\\u0645."
t["Ten minutes under water sounds like a miracle."] = "\\u0639\\u0634\\u0631 \\u062F\\u0642\\u0627\\u064A\\u0642 \\u062A\\u062D\\u062A \\u0627\\u0644\\u0645\\u064A \\u0628\\u062A\\u0634\\u0628\\u0647 \\u0627\\u0644\\u0645\\u0639\\u062C\\u0632\\u0629."
t["Ten minutes. I've named every fly in this room."] = "\\u0639\\u0634\\u0631 \\u062F\\u0642\\u0627\\u064A\\u0642. \\u0633\\u0645\\u0651\\u064A\\u062A \\u0643\\u0644 \\u062F\\u0628\\u0627\\u0646\\u0629 \\u0628\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629."
t["Ten quiet minutes, then I can function properly."] = "\\u0639\\u0634\\u0631 \\u062F\\u0642\\u0627\\u064A\\u0642 \\u0647\\u062F\\u0648\\u0621\\u060C \\u0648\\u0628\\u0631\\u062C\\u0639 \\u0637\\u0628\\u064A\\u0639\\u064A\\u0629."
t["Test the trick in daylight. Then tell me whether it works."] = "\\u062C\\u0631\\u0628 \\u0627\\u0644\\u062D\\u0631\\u0643\\u0629 \\u0628\\u0627\\u0644\\u0646\\u0647\\u0627\\u0631. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0642\\u0644\\u064A \\u0625\\u0630\\u0627 \\u0632\\u0628\\u0637\\u062A."
t["Testing the line. Anybody out there?"] = "\\u0639\\u0645 \\u062C\\u0631\\u0628 \\u0627\\u0644\\u062E\\u0637. \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0647\\u0648\\u0646\\u064A\\u0643\\u061F"
t["Testing. Don't make me walk over there to find out."] = "\\u062A\\u062C\\u0631\\u0628\\u0629. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0645\\u0634\\u064A \\u0644\\u0639\\u0646\\u062F\\u0643 \\u0644\\u0623\\u0639\\u0631\\u0641."
t["Thank you - I'm up!"] = "\\u0634\\u0643\\u0631\\u0627 - \\u0642\\u0645\\u062A!"
t["Thank you for coming over."] = "\\u0634\\u0643\\u0631\\u0627\\u064B \\u0625\\u0646\\u0643 \\u0627\\u062C\\u064A\\u062A."
t["Thank you for every mile we walked as a team."] = "\\u0634\\u0643\\u0631\\u0627 \\u0639\\u0643\\u0644 \\u0645\\u064A\\u0644 \\u0645\\u0634\\u064A\\u0646\\u0627\\u0647 \\u0633\\u0648\\u0627."
t["Thank you for every ordinary morning."] = "\\u0634\\u0643\\u0631\\u0627 \\u0639\\u0643\\u0644 \\u0635\\u0628\\u062D\\u064A\\u0629 \\u0639\\u0627\\u062F\\u064A\\u0629."
t["Thank you for giving a stranger somewhere safe to stop."] = "\\u0634\\u0643\\u0631\\u0627 \\u0625\\u0646\\u0643 \\u0639\\u0637\\u064A\\u062A \\u0648\\u062D\\u062F\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629 \\u0645\\u0637\\u0631\\u062D \\u0623\\u0645\\u0627\\u0646 \\u062A\\u0648\\u0642\\u0641 \\u0641\\u064A\\u0647."
t["Thank you for making me part of something again."] = "\\u0634\\u0643\\u0631\\u0627 \\u0625\\u0646\\u0643 \\u0631\\u062C\\u0639\\u062A\\u0646\\u064A \\u062C\\u0632\\u0621 \\u0645\\u0646 \\u0634\\u064A."
t["Thank you for staying close. I am all right now."] = "\\u0634\\u0643\\u0631\\u0627\\u064B \\u0625\\u0646\\u0643 \\u0636\\u0644\\u064A\\u062A \\u0642\\u0631\\u064A\\u0628. \\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629 \\u0647\\u0644\\u0623."
t["Thank you for taking a chance on me. Now take your chance to run."] = "\\u0634\\u0643\\u0631\\u0627 \\u0625\\u0646\\u0643 \\u062E\\u0627\\u0637\\u0631\\u062A \\u0641\\u064A\\u064A. \\u0647\\u0644\\u0623 \\u062E\\u0627\\u0637\\u0631 \\u0648\\u0627\\u0647\\u0631\\u0628."
t["Thank you. I am proud that I could help."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0648\\u0641\\u062E\\u0648\\u0631\\u0629 \\u0625\\u0646\\u064A \\u0642\\u062F\\u0631\\u062A \\u0633\\u0627\\u0639\\u062F."
t["Thank you. I needed to hear that."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0643\\u0646\\u062A \\u0645\\u062D\\u062A\\u0627\\u062C\\u0629 \\u0627\\u0633\\u0645\\u0639\\u0647\\u0627."
t["Thank you. I'll use it to keep us safe."] = "\\u0634\\u0643\\u0631\\u0627 \\u0625\\u0644\\u0643. \\u0631\\u062D \\u0627\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647 \\u0644\\u0623\\u062D\\u0645\\u064A\\u0646\\u0627."
t["Thank you. This might keep both of us alive."] = "\\u0634\\u0643\\u0631\\u0627. \\u064A\\u0645\\u0643\\u0646 \\u064A\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646."
t["Thanks for not running."] = "\\u0634\\u0643\\u0631\\u0627\\u064B \\u0625\\u0646\\u0643 \\u0645\\u0627 \\u0647\\u0631\\u0628\\u062A."
t["Thanks for trusting me with this."] = "\\u0634\\u0643\\u0631\\u0627 \\u0625\\u0646\\u0643 \\u0623\\u0645\\u0646\\u062A\\u0646\\u064A \\u0639\\u0644\\u064A\\u0647."
t["Thanks for watching the approach."] = "\\u064A\\u0633\\u0644\\u0645\\u0648 \\u0639\\u0627\\u0644\\u062D\\u0631\\u0627\\u0633\\u0629."
t["Thanks, but let us save the celebration until the work is done."] = "\\u0634\\u0643\\u0631\\u0627\\u064B\\u060C \\u0628\\u0633 \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0623\\u062C\\u0644 \\u0627\\u0644\\u0627\\u062D\\u062A\\u0641\\u0627\\u0644 \\u0644\\u0646\\u062E\\u0644\\u0635 \\u0627\\u0644\\u0634\\u063A\\u0644."
t["Thanks. For a minute, I remembered something besides July."] = "\\u0634\\u0643\\u0631\\u064B\\u0627. \\u0644\\u062F\\u0642\\u064A\\u0642\\u0629\\u060C \\u062A\\u0630\\u0643\\u0631\\u062A \\u0634\\u064A \\u063A\\u064A\\u0631 \\u062A\\u0645\\u0648\\u0632."
t["Thanks. For now, let's stay focused."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0647\\u0644\\u0623 \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0631\\u0643\\u0632."
t["Thanks. I needed a person, not a solution."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0643\\u0646\\u062A \\u0645\\u062D\\u062A\\u0627\\u062C\\u0629 \\u0625\\u0646\\u0633\\u0627\\u0646\\u060C \\u0645\\u0648 \\u062D\\u0644."
t["Thanks. I was getting lost in my own head."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0643\\u0646\\u062A \\u0639\\u0645 \\u0636\\u064A\\u0639 \\u062C\\u0648\\u0627 \\u0631\\u0627\\u0633\\u064A."
t["Thanks. I'll be thinking about that at three in the morning."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0631\\u062D \\u0641\\u0643\\u0631 \\u0641\\u064A\\u0647\\u0627 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u062A\\u0644\\u0627\\u062A\\u0629 \\u0627\\u0644\\u0635\\u0628\\u062D."
t["Thanks. I'll save it for when we really need it."] = "\\u0634\\u0643\\u0631\\u0627. \\u0628\\u062E\\u0628\\u064A\\u0647 \\u0644\\u0648\\u0642\\u062A \\u0646\\u062D\\u062A\\u0627\\u062C\\u0647 \\u0639\\u0646 \\u062C\\u062F."
t["Thanks. I'll use it when I need it."] = "\\u0634\\u0643\\u0631\\u0627. \\u0628\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647 \\u0648\\u0642\\u062A \\u0627\\u0644\\u0644\\u0632\\u0648\\u0645."
t["Thanks. It is good to know the effort mattered."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0645\\u0646\\u064A\\u062D \\u0627\\u0639\\u0631\\u0641 \\u0625\\u0646 \\u0627\\u0644\\u062A\\u0639\\u0628 \\u0645\\u0627 \\u0631\\u0627\\u062D \\u0639\\u0627\\u0644\\u0641\\u0627\\u0636\\u064A."
t["Thanks. Let me have that one for a minute."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u062A\\u0647\\u0646\\u0649 \\u0641\\u064A\\u0647\\u0627 \\u062F\\u0642\\u064A\\u0642\\u0629."
t["Thanks. Let's not make success an excuse to get careless."] = "\\u0634\\u0643\\u0631\\u0627\\u064B. \\u0628\\u0633 \\u0644\\u0627 \\u0646\\u062E\\u0644\\u064A \\u0627\\u0644\\u0646\\u062C\\u0627\\u062D \\u064A\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0647\\u0645\\u0644."
t["That advice may outlast the station."] = "\\u0647\\u0627\\u0644\\u0646\\u0635\\u064A\\u062D\\u0629 \\u064A\\u0645\\u0643\\u0646 \\u062A\\u0639\\u064A\\u0634 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062D\\u0637\\u0629."
t["That alarm is a dinner bell. Every one of them heard it."] = "\\u0647\\u0627\\u0644\\u0625\\u0646\\u0630\\u0627\\u0631 \\u062C\\u0631\\u0633 \\u0639\\u0634\\u0627. \\u0643\\u0644\\u0647\\u0646 \\u0633\\u0645\\u0639\\u0648\\u0647."
t["That attempt at %1 didn't work. I'm waiting %2 before another try."] = "\\u0645\\u062D\\u0627\\u0648\\u0644\\u062A\\u064A \\u0628\\u0640%1 \\u0645\\u0627 \\u0632\\u0628\\u0637\\u062A. \\u0639\\u0645 \\u0627\\u0633\\u062A\\u0646\\u0649 %2 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062C\\u0631\\u0628."
t["That barricade needs leverage. Have we got a crowbar?"] = "\\u0647\\u0627\\u0644\\u062D\\u0627\\u062C\\u0632 \\u0628\\u062F\\u0648 \\u0642\\u0648\\u0629. \\u0639\\u0646\\u0627 \\u0639\\u062A\\u0644\\u0629\\u061F"
t["That barrier's going. We should find a better place to stand."] = "\\u0647\\u0627\\u0644\\u062D\\u0627\\u062C\\u0632 \\u0639\\u0645 \\u064A\\u0631\\u0648\\u062D. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0645\\u0637\\u0631\\u062D \\u0623\\u062D\\u0633\\u0646 \\u0646\\u0648\\u0642\\u0641 \\u0641\\u064A\\u0647."
t["That barstool's got a dent shaped like a man. He's not coming back for it."] = "\\u0647\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0641\\u064A\\u0647 \\u0637\\u0628\\u0639\\u0629 \\u0642\\u062F \\u0632\\u0644\\u0645\\u0629. \\u0645\\u0648 \\u0631\\u0627\\u062C\\u0639 \\u0639\\u0644\\u064A\\u0647\\u0627."
t["That bought me a few hours."] = "\\u0647\\u064A\\u0643 \\u0645\\u0634\\u064A \\u062D\\u0627\\u0644\\u064A \\u0643\\u0645 \\u0633\\u0627\\u0639\\u0629."
t["That came in from a long way off."] = "\\u0647\\u0627\\u062F \\u0625\\u062C\\u0627 \\u0645\\u0646 \\u0628\\u0639\\u064A\\u062F \\u0643\\u062A\\u064A\\u0631."
t["That can be tomorrow's problem. Tonight the walls held."] = "\\u0647\\u0627\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0628\\u0643\\u0631\\u0627. \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629 \\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0635\\u0645\\u062F\\u062A."
t["That carried. Let's move before the listeners arrive."] = "\\u0648\\u0635\\u0644 \\u0627\\u0644\\u0635\\u0648\\u062A \\u0628\\u0639\\u064A\\u062F. \\u064A\\u0644\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0648\\u0635\\u0644\\u0648\\u0627 \\u0627\\u0644\\u0644\\u064A \\u0633\\u0645\\u0639\\u0648\\u0627."
t["That didn't feel like an accident."] = "\\u0647\\u064A \\u0645\\u0627 \\u062D\\u0633\\u064A\\u062A\\u0647\\u0627 \\u063A\\u0644\\u0637\\u0629."
t["That didn't go well..."] = "\\u0645\\u0627 \\u0645\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644..."
t["That dressing's filthy. Let's change it."] = "\\u0647\\u0627\\u0644\\u0634\\u0627\\u0634 \\u0645\\u0642\\u0631\\u0641. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u063A\\u064A\\u0631\\u0647."
t["That drill sound still gives me chills. Just the memory."] = "\\u0635\\u0648\\u062A \\u062F\\u0631\\u064A\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0644\\u0633\\u0627 \\u0628\\u064A\\u0642\\u0634\\u0639\\u0631\\u0646\\u064A. \\u0628\\u0633 \\u0645\\u0646 \\u0627\\u0644\\u0630\\u0643\\u0631\\u0649."
t["That exit offers teeth instead of daylight. I'm staying clear."] = "\\u0647\\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0641\\u064A\\u0647 \\u0633\\u0646\\u0627\\u0646 \\u0628\\u062F\\u0627\\u0644 \\u0627\\u0644\\u0636\\u0648. \\u0639\\u0645 \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F\\u0629."
t["That fence looked taller from down there."] = "\\u0645\\u0646 \\u062A\\u062D\\u062A \\u0643\\u0627\\u0646 \\u0645\\u0628\\u064A\\u0646 \\u0623\\u0639\\u0644\\u0649."
t["That fight doesn't add up. I'm moving out."] = "\\u0647\\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0645\\u0648 \\u0631\\u0627\\u0643\\u0628. \\u0623\\u0646\\u0627 \\u0637\\u0627\\u0644\\u0639\\u0629."
t["That gnome is judging me harder than the living do."] = "\\u0647\\u0627\\u0644\\u0642\\u0632\\u0645 \\u0639\\u0645 \\u064A\\u062D\\u0643\\u0645 \\u0639\\u0644\\u064A\\u0651 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0627\\u064A\\u0634\\u064A\\u0646."
t["That grave won't dig itself. Find me a shovel."] = "\\u0647\\u0627\\u0644\\u0642\\u0628\\u0631 \\u0645\\u0627 \\u0631\\u062D \\u064A\\u062D\\u0641\\u0631 \\u062D\\u0627\\u0644\\u0647. \\u062F\\u0628\\u0631\\u0644\\u064A \\u0643\\u0631\\u064A\\u0643."
t["That helped more than I expected."] = "\\u0641\\u0627\\u062F\\u062A\\u0646\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A."
t["That helped. Not a miracle. Enough."] = "\\u0641\\u0627\\u062F\\u062A\\u0646\\u064A. \\u0645\\u0648 \\u0645\\u0639\\u062C\\u0632\\u0629. \\u0628\\u0633 \\u0628\\u062A\\u0643\\u0641\\u064A."
t["That horn will bring company. Let's avoid the welcoming committee."] = "\\u0647\\u0627\\u0644\\u0632\\u0645\\u0648\\u0631 \\u0631\\u062D \\u064A\\u062C\\u064A\\u0628 \\u0636\\u064A\\u0648\\u0641. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0647\\u0631\\u0628 \\u0645\\u0646 \\u0644\\u062C\\u0646\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062A\\u0642\\u0628\\u0627\\u0644."
t["That host talks like nothing outside has changed."] = "\\u0647\\u0627\\u0644\\u0645\\u0630\\u064A\\u0639 \\u0639\\u0645 \\u064A\\u062D\\u0643\\u064A \\u0643\\u0623\\u0646\\u0648 \\u0628\\u0631\\u0627 \\u0645\\u0627 \\u062A\\u063A\\u064A\\u0631 \\u0634\\u064A."
t["That hum sounds like every kitchen I used to know."] = "\\u0647\\u0627\\u0644\\u0637\\u0646\\u064A\\u0646 \\u0645\\u062A\\u0644 \\u0643\\u0644 \\u0645\\u0637\\u0628\\u062E \\u0643\\u0646\\u062A \\u0627\\u0639\\u0631\\u0641\\u0647."
t["That is a terrible idea. Keep watching."] = "\\u0647\\u064A \\u0641\\u0643\\u0631\\u0629 \\u0632\\u0641\\u062A. \\u0643\\u0645\\u0651\\u0644 \\u0641\\u0631\\u062C\\u0629."
t["That is close enough. Turn around."] = "\\u0644\\u0647\\u0648\\u0646 \\u0648\\u0628\\u0633. \\u0644\\u0641 \\u0648\\u0627\\u0631\\u062C\\u0639."
t["That is enough for now. Tell me when we leave."] = "\\u0647\\u0627\\u062F \\u0628\\u064A\\u0643\\u0641\\u064A \\u0647\\u0644\\u0623. \\u0642\\u0644\\u064A \\u0625\\u064A\\u0645\\u062A \\u0645\\u0646\\u0637\\u0644\\u0639."
t["That is enough hope to carry for one day."] = "\\u0647\\u0627\\u062F \\u0623\\u0645\\u0644 \\u0628\\u0643\\u0641\\u064A \\u0644\\u064A\\u0648\\u0645 \\u0648\\u0627\\u062D\\u062F."
t["That is going in the trash, not the pan."] = "\\u0647\\u0627\\u062F \\u0645\\u0643\\u0627\\u0646\\u0647 \\u0627\\u0644\\u0632\\u0628\\u0627\\u0644\\u0629\\u060C \\u0645\\u0648 \\u0627\\u0644\\u0645\\u0642\\u0644\\u0627\\u064A\\u0629."
t["That is it! Get out!"] = "\\u062E\\u0644\\u0635! \\u0628\\u0631\\u0627!"
t["That is one more supper we did not have before."] = "\\u0647\\u064A \\u0639\\u0634\\u0648\\u0629 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0639\\u0646\\u0627."
t["That is personal. Give me a little more time."] = "\\u0647\\u0627\\u062F \\u0634\\u064A \\u0634\\u062E\\u0635\\u064A. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0648\\u0642\\u062A \\u0643\\u0645\\u0627\\u0646."
t["That is what surviving tastes like."] = "\\u0647\\u0627\\u062F \\u0637\\u0639\\u0645 \\u0627\\u0644\\u0628\\u0642\\u0627\\u0621 \\u0639\\u0627\\u0644\\u062D\\u064A\\u0627\\u0629."
t["That job is blocked here. A better position might let me finish."] = "\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0645\\u0633\\u0643\\u0631\\u0629 \\u0647\\u0648\\u0646. \\u064A\\u0645\\u0643\\u0646 \\u0645\\u0646 \\u0645\\u0637\\u0631\\u062D \\u0623\\u062D\\u0633\\u0646 \\u0628\\u062E\\u0644\\u0635\\u0647\\u0627."
t["That joke died before they did."] = "\\u0647\\u0627\\u0644\\u0646\\u0643\\u062A\\u0629 \\u0645\\u0627\\u062A\\u062A \\u0642\\u0628\\u0644\\u0647\\u0646."
t["That joke was old before the dead started walking."] = "\\u0647\\u0627\\u0644\\u0646\\u0643\\u062A\\u0629 \\u0643\\u0627\\u0646\\u062A \\u0642\\u062F\\u064A\\u0645\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0645\\u0634\\u0648\\u0627 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649."
t["That keepsake reminds me who I was before all this."] = "\\u0647\\u0627\\u0644\\u062A\\u0630\\u0643\\u0627\\u0631 \\u0628\\u064A\\u0630\\u0643\\u0631\\u0646\\u064A \\u0645\\u064A\\u0646 \\u0643\\u0646\\u062A \\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F."
t["That kind of quiet is exactly the kind I don't trust."] = "\\u0647\\u0627\\u0644\\u0646\\u0648\\u0639 \\u0645\\u0646 \\u0627\\u0644\\u0647\\u062F\\u0648\\u0621 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637 \\u0645\\u0627 \\u0628\\u062B\\u0642 \\u0641\\u064A\\u0647."
t["That kind of quiet is exactly the kind I don't trust. Hell no."] = "\\u0647\\u0627\\u0644\\u0646\\u0648\\u0639 \\u0645\\u0646 \\u0627\\u0644\\u0647\\u062F\\u0648\\u0621 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637 \\u0645\\u0627 \\u0628\\u062B\\u0642 \\u0641\\u064A\\u0647. \\u0648\\u0644\\u0627 \\u0628\\u0627\\u0644\\u062C\\u062D\\u064A\\u0645."
t["That landed on me. Watch it."] = "\\u0647\\u064A \\u0625\\u062C\\u062A \\u0641\\u064A\\u0646\\u064A. \\u0627\\u0646\\u062A\\u0628\\u0647."
t["That last page stayed with me longer than I expected."] = "\\u0622\\u062E\\u0631 \\u0635\\u0641\\u062D\\u0629 \\u0636\\u0644\\u062A \\u0645\\u0639\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A."
t["That leg needs a splint. Hold still."] = "\\u0647\\u0627\\u0644\\u0625\\u062C\\u0631 \\u0628\\u062F\\u0647\\u0627 \\u062C\\u0628\\u064A\\u0631\\u0629. \\u062B\\u0628\\u062A."
t["That looks easier than they make it sound. Famous last words."] = "\\u0634\\u0643\\u0644\\u0647\\u0627 \\u0623\\u0633\\u0647\\u0644 \\u0645\\u0646 \\u062D\\u0643\\u064A\\u0647\\u0645. \\u0648\\u0647\\u0627\\u0644\\u062D\\u0643\\u064A \\u0628\\u0627\\u0644\\u0630\\u0627\\u062A \\u0628\\u064A\\u0648\\u062F\\u0651\\u064A \\u0628\\u062F\\u0627\\u0647\\u064A\\u0629."
