t["That's no accident anymore."] = "\\u0647\\u0627\\u062F \\u0645\\u0627 \\u0639\\u0627\\u062F \\u063A\\u0644\\u0637\\u0629."
t["That's not a fight. That's a pile-on. I'm out."] = "\\u0647\\u064A \\u0645\\u0648 \\u0645\\u0639\\u0631\\u0643\\u0629. \\u0647\\u064A \\u0643\\u0648\\u0645\\u0629. \\u0623\\u0646\\u0627 \\u0628\\u0631\\u0627."
t["That's not an intrusive thought. That's a confession."] = "\\u0647\\u0627\\u062F \\u0645\\u0648 \\u0648\\u0633\\u0648\\u0627\\u0633. \\u0647\\u0627\\u062F \\u0627\\u0639\\u062A\\u0631\\u0627\\u0641."
t["That's one less reminder to look at."] = "\\u0630\\u0643\\u0631\\u0649 \\u0623\\u0642\\u0644 \\u0646\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0647\\u0627."
t["That's one weapon I refuse to holster in a hurry."] = "\\u0647\\u0627\\u062F \\u0633\\u0644\\u0627\\u062D \\u0645\\u0627 \\u0628\\u062F\\u062E\\u0644\\u0647 \\u0628\\u0627\\u0644\\u063A\\u0644\\u0627\\u0641 \\u0639\\u0627\\u0644\\u0633\\u0631\\u064A\\u0639."
t["That's one!"] = "\\u0647\\u0627\\u062F \\u0648\\u0627\\u062D\\u062F!"
t["That's sorted, then. More or less. Mostly more."] = "\\u0647\\u064A\\u0643 \\u062E\\u0644\\u0635\\u062A\\u060C \\u064A\\u0639\\u0646\\u064A. \\u062A\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B. \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u063A\\u0644\\u0628 \\u062A\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["That's the crop collected."] = "\\u0647\\u064A\\u0643 \\u0644\\u0645\\u0651\\u064A\\u0646\\u0627 \\u0627\\u0644\\u0632\\u0631\\u0639."
t["That's the most normal thing you've said all week."] = "\\u0647\\u0627\\u062F \\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0637\\u0628\\u064A\\u0639\\u064A \\u0642\\u0644\\u062A\\u0647 \\u0645\\u0646 \\u0623\\u0648\\u0644 \\u0627\\u0644\\u062C\\u0645\\u0639\\u0629."
t["That's the trip. Count heads. We're all here."] = "\\u062E\\u0644\\u0635 \\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631. \\u0639\\u062F\\u0648\\u0627. \\u0643\\u0644\\u0646\\u0627 \\u0647\\u0648\\u0646."
t["That's three of them. I'm not going in there."] = "\\u0647\\u062F\\u0648\\u0644 \\u062A\\u0644\\u0627\\u062A\\u0629. \\u0645\\u0648 \\u0641\\u0627\\u064A\\u062A\\u0629 \\u0644\\u0647\\u0646\\u064A\\u0643."
t["That's three. I'm not counting. I'm absolutely counting."] = "\\u0647\\u062F\\u0648\\u0644 \\u062A\\u0644\\u0627\\u062A\\u0629. \\u0645\\u0648 \\u0639\\u0645 \\u0639\\u062F. \\u0644\\u0627, \\u0639\\u0645 \\u0639\\u062F \\u0648\\u0639\\u062F."
t["That's twice. I'm staying back."] = "\\u0647\\u064A \\u0645\\u0631\\u062A\\u064A\\u0646. \\u0631\\u062D \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F\\u0629."
t["That's wood giving way. Give it a minute and it won't be a door."] = "\\u0647\\u0627\\u062F \\u062E\\u0634\\u0628 \\u0639\\u0645 \\u064A\\u0646\\u0643\\u0633\\u0631. \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0648\\u0645\\u0627 \\u0628\\u064A\\u0636\\u0644 \\u0628\\u0627\\u0628."
t["The antenna's crooked, but so are we."] = "\\u0627\\u0644\\u0623\\u0646\\u062A\\u064A\\u0646 \\u0645\\u0639\\u0648\\u062C\\u060C \\u0628\\u0633 \\u0646\\u062D\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["The apocalypse has really lowered the bar for privacy."] = "\\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0646\\u0632\\u0644\\u062A \\u0633\\u0642\\u0641 \\u0627\\u0644\\u062E\\u0635\\u0648\\u0635\\u064A\\u0629 \\u0643\\u062A\\u064A\\u0631."
t["The approach is blocked. I'm finding a way to finish %1."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0633\\u0643\\u0631\\u0629. \\u0639\\u0645 \\u062F\\u0648\\u0631 \\u0643\\u064A\\u0641 \\u062E\\u0644\\u0651\\u0635 %1."
t["The author calls hope a discipline. I call it a fight worth having."] = "\\u0627\\u0644\\u0643\\u0627\\u062A\\u0628 \\u0628\\u064A\\u0633\\u0645\\u064A \\u0627\\u0644\\u0623\\u0645\\u0644 \\u0627\\u0646\\u0636\\u0628\\u0627\\u0637. \\u0623\\u0646\\u0627 \\u0628\\u0633\\u0645\\u064A\\u0647 \\u0645\\u0639\\u0631\\u0643\\u0629 \\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644."
t["The author skips a step. Can you spot it, %1?"] = "\\u0627\\u0644\\u0643\\u0627\\u062A\\u0628 \\u0646\\u0637 \\u062E\\u0637\\u0648\\u0629. \\u0641\\u064A\\u0643 \\u062A\\u0644\\u0627\\u0642\\u064A\\u0647\\u0627 \\u064A\\u0627 %1\\u061F"
t["The author was wrong about courage. The rest might be right."] = "\\u0627\\u0644\\u0643\\u0627\\u062A\\u0628 \\u063A\\u0644\\u0637\\u0627\\u0646 \\u0639\\u0646 \\u0627\\u0644\\u0634\\u062C\\u0627\\u0639\\u0629. \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A \\u064A\\u0645\\u0643\\u0646 \\u0635\\u062D."
t["The best lesson was to pay attention to the person beside me."] = "\\u0623\\u062D\\u0633\\u0646 \\u062F\\u0631\\u0633 \\u0643\\u0627\\u0646 \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0644\\u064A \\u062C\\u0646\\u0628\\u064A."
t["The bleach smells better than what's under it."] = "\\u0631\\u064A\\u062D\\u0629 \\u0627\\u0644\\u0643\\u0644\\u0648\\u0631 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u062A\\u062D\\u062A\\u0647\\u0627."
t["The blood's gone. The memory can wait."] = "\\u0627\\u0644\\u062F\\u0645 \\u0631\\u0627\\u062D. \\u0627\\u0644\\u0630\\u0643\\u0631\\u0649 \\u0628\\u062A\\u0633\\u062A\\u0646\\u0649."
t["The board says help is one call away. Telephone service not included."] = "\\u0627\\u0644\\u0644\\u0648\\u062D \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0639\\u062F\\u0629 \\u0639\\u0628\\u0639\\u062F \\u062A\\u0644\\u0641\\u0648\\u0646. \\u062E\\u062F\\u0645\\u0629 \\u0627\\u0644\\u062A\\u0644\\u0641\\u0648\\u0646 \\u0645\\u0648 \\u0645\\u0634\\u0645\\u0648\\u0644\\u0629."
t["The boards are holding firm. My fingers aren't a crowbar."] = "\\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u062D \\u062B\\u0627\\u0628\\u062A\\u0629. \\u0648\\u0623\\u0635\\u0627\\u0628\\u064A\\u0639\\u064A \\u0645\\u0648 \\u0639\\u062A\\u0644\\u0629."
t["The boards are stuck fast. We need a proper tool."] = "\\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u062D \\u0644\\u0627\\u0632\\u0642\\u0629 \\u0643\\u062A\\u064A\\u0631. \\u0628\\u062F\\u0646\\u0627 \\u0639\\u062F\\u0629 \\u0639\\u062F\\u0644\\u0629."
t["The book asks who we are alone. I want to know who we are together."] = "\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0628\\u064A\\u0633\\u0623\\u0644 \\u0645\\u064A\\u0646 \\u0646\\u062D\\u0646\\u0627 \\u0644\\u062D\\u0627\\u0644\\u0646\\u0627. \\u0623\\u0646\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0639\\u0631\\u0641 \\u0645\\u064A\\u0646 \\u0646\\u062D\\u0646\\u0627 \\u0645\\u0639 \\u0628\\u0639\\u0636."
t["The book raised more questions than it answered. Fair enough."] = "\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0637\\u0631\\u062D \\u0623\\u0633\\u0626\\u0644\\u0629 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0627 \\u062C\\u0627\\u0648\\u0628. \\u0645\\u0627\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644."
t["The brace is crude, but it'll hold."] = "\\u0627\\u0644\\u062C\\u0628\\u064A\\u0631\\u0629 \\u0628\\u062F\\u0627\\u0626\\u064A\\u0629\\u060C \\u0628\\u0633 \\u0631\\u062D \\u062A\\u0645\\u0633\\u0643."
t["The camp layout finally supports the work."] = "\\u0623\\u062E\\u064A\\u0631\\u0627\\u064B \\u062A\\u0631\\u062A\\u064A\\u0628 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0635\\u0627\\u0631 \\u0628\\u064A\\u062E\\u062F\\u0645 \\u0627\\u0644\\u0634\\u063A\\u0644."
t["The cloth is clean. I can't promise the rest."] = "\\u0627\\u0644\\u0642\\u0645\\u0627\\u0634 \\u0646\\u0636\\u064A\\u0641. \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A \\u0645\\u0627 \\u0628\\u0648\\u0639\\u062F\\u0643 \\u0641\\u064A\\u0647."
t["The cold room's warm now. That's not how it's supposed to work."] = "\\u0627\\u0644\\u0628\\u0631\\u0651\\u0627\\u062F \\u0635\\u0627\\u0631 \\u062F\\u0627\\u0641\\u064A. \\u0645\\u0648 \\u0647\\u064A\\u0643 \\u0627\\u0644\\u0645\\u0641\\u0631\\u0648\\u0636."
t["The county can send me a bill when it reopens."] = "\\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u062A\\u0628\\u0639\\u062A\\u0644\\u064A \\u0641\\u0627\\u062A\\u0648\\u0631\\u0629 \\u0644\\u0645\\u0627 \\u062A\\u0641\\u062A\\u062D."
t["The county has never been this quiet, or this crowded."] = "\\u0639\\u0645\\u0631\\u0647\\u0627 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0647\\u064A\\u0643 \\u0647\\u0627\\u062F\\u064A\\u0629\\u060C \\u0623\\u0648 \\u0647\\u064A\\u0643 \\u0645\\u0632\\u062F\\u062D\\u0645\\u0629."
t["The crop is sick. Apparently we needed one more problem."] = "\\u0627\\u0644\\u0632\\u0631\\u0639 \\u0645\\u0631\\u064A\\u0636. \\u0627\\u0644\\u0638\\u0627\\u0647\\u0631 \\u0643\\u0627\\u0646 \\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["The current job is %1 at %2."] = "\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u062D\\u0627\\u0644\\u064A\\u0629 %1 \\u0639\\u0646\\u062F %2."
t["The dark isn't watching back. It is, though."] = "\\u0627\\u0644\\u0639\\u062A\\u0645\\u0629 \\u0645\\u0648 \\u0639\\u0645 \\u062A\\u0631\\u0627\\u0642\\u0628. \\u0628\\u0644\\u0649\\u060C \\u0639\\u0645 \\u062A\\u0631\\u0627\\u0642\\u0628."
t["The dark makes my thoughts louder. Real asshole move, dark."] = "\\u0627\\u0644\\u0639\\u062A\\u0645\\u0629 \\u0628\\u062A\\u0639\\u0644\\u0651\\u064A \\u0635\\u0648\\u062A \\u0623\\u0641\\u0643\\u0627\\u0631\\u064A. \\u062D\\u0631\\u0643\\u0629 \\u0642\\u0630\\u0631\\u0629 \\u0645\\u0646\\u0643 \\u064A\\u0627 \\u0639\\u062A\\u0645\\u0629."
t["The dark makes my thoughts louder. Rude of it."] = "\\u0627\\u0644\\u0639\\u062A\\u0645\\u0629 \\u0628\\u062A\\u0639\\u0644\\u0651\\u064A \\u0635\\u0648\\u062A \\u0623\\u0641\\u0643\\u0627\\u0631\\u064A. \\u0642\\u0644\\u0629 \\u0630\\u0648\\u0642 \\u0645\\u0646\\u0647\\u0627."
t["The dead are not getting these plants, and neither are the bugs."] = "\\u0644\\u0627 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0631\\u062D \\u064A\\u0627\\u062E\\u062F\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0632\\u0631\\u0639\\u060C \\u0648\\u0644\\u0627 \\u0627\\u0644\\u062D\\u0634\\u0631\\u0627\\u062A."
t["The dead can have the street. I'm claiming this shower."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0625\\u0644\\u0647\\u0645 \\u0627\\u0644\\u0634\\u0627\\u0631\\u0639. \\u0648\\u0623\\u0646\\u0627 \\u0647\\u0627\\u0644\\u062F\\u0648\\u0634 \\u0625\\u0644\\u064A."
t["The dead can still hear."] = "\\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0644\\u0633\\u0627 \\u0628\\u064A\\u0633\\u0645\\u0639\\u0648\\u0627."
t["The dead can't swim. The fish have been keeping quiet about it."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u0639\\u0631\\u0641\\u0648\\u0627 \\u064A\\u0633\\u0628\\u062D\\u0648\\u0627. \\u0648\\u0627\\u0644\\u0633\\u0645\\u0643 \\u0633\\u0627\\u0643\\u062A \\u0639\\u0646 \\u0647\\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639."
t["The dead do not teach. The living still do."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u0639\\u0644\\u0645\\u0648\\u0627. \\u0627\\u0644\\u0639\\u0627\\u064A\\u0634\\u064A\\u0646 \\u0644\\u0633\\u0627 \\u0628\\u064A\\u0639\\u0644\\u0645\\u0648\\u0627."
t["The dead don't remember us. That should help. It doesn't."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u062A\\u0630\\u0643\\u0631\\u0648\\u0646\\u0627. \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0631\\u064A\\u062D\\u0646\\u064A \\u0647\\u0627\\u0644\\u0634\\u064A. \\u0645\\u0627 \\u0628\\u064A\\u0631\\u064A\\u062D\\u0646\\u064A."
t["The dead never get tired. That's bullshit, is what that is."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u062A\\u0639\\u0628\\u0648\\u0627. \\u0647\\u0627\\u062F \\u0634\\u064A \\u0628\\u064A\\u0642\\u0647\\u0631\\u060C \\u064A\\u0644\\u0639\\u0646\\u0647."
t["The dead never get tired. That's not fair, is it."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u062A\\u0639\\u0628\\u0648\\u0627. \\u0645\\u0648 \\u0639\\u062F\\u0644\\u060C \\u0635\\u062D\\u061F"
t["The dead own the front porch. We'll try the back."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0644\\u0643\\u0648\\u0627 \\u0627\\u0644\\u0628\\u0631\\u0646\\u062F\\u0629. \\u0645\\u0646\\u062C\\u0631\\u0628 \\u0645\\u0646 \\u0648\\u0631\\u0627."
t["The dial has more ghosts than stations now."] = "\\u0627\\u0644\\u0645\\u0624\\u0634\\u0631 \\u0635\\u0627\\u0631 \\u0641\\u064A\\u0647 \\u0623\\u0634\\u0628\\u0627\\u062D \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062D\\u0637\\u0627\\u062A."
t["The dial says we're together. The air can prove it."] = "\\u0627\\u0644\\u0645\\u0624\\u0634\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0646\\u062D\\u0646\\u0627 \\u0633\\u0648\\u0627. \\u0627\\u0644\\u0647\\u0648\\u0627 \\u0628\\u064A\\u062B\\u0628\\u062A\\u0647\\u0627."
t["The dial sticks. Everything else around here does too."] = "\\u0627\\u0644\\u0645\\u0624\\u0634\\u0631 \\u0645\\u0639\\u0644\\u0642. \\u0645\\u062A\\u0644 \\u0643\\u0644 \\u0634\\u064A \\u0647\\u0648\\u0646."
t["The dirt has the advantage. It has a shovel shortage on its side."] = "\\u0627\\u0644\\u062A\\u0631\\u0627\\u0628 \\u063A\\u0627\\u0644\\u0628\\u0646\\u064A\\u060C \\u0648\\u0646\\u0642\\u0635 \\u0627\\u0644\\u0643\\u0631\\u064A\\u0643\\u0627\\u062A \\u0648\\u0627\\u0642\\u0641 \\u0628\\u0635\\u0641\\u0651\\u0647."
t["The dishes stay clean now. Nobody's here to dirty them."] = "\\u0627\\u0644\\u0635\\u062D\\u0648\\u0646 \\u0628\\u062A\\u0636\\u0644 \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0647\\u0644\\u0623. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0648\\u0633\\u062E\\u0647\\u0627."
t["The end feels smaller with someone beside you."] = "\\u0627\\u0644\\u0646\\u0647\\u0627\\u064A\\u0629 \\u0628\\u062A\\u0635\\u063A\\u0631 \\u0644\\u0645\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u062C\\u0646\\u0628\\u0643."
t["The ending earned its nerve. I'll give it that."] = "\\u0627\\u0644\\u0646\\u0647\\u0627\\u064A\\u0629 \\u062C\\u0631\\u064A\\u0626\\u0629 \\u0648\\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644. \\u0628\\u0639\\u062A\\u0631\\u0641\\u0644\\u0647\\u0627."
t["The engine's still here. They never made it out."] = "\\u0633\\u064A\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0625\\u0637\\u0641\\u0627\\u0621 \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646. \\u0645\\u0627 \\u0644\\u062D\\u0642\\u0648\\u0627 \\u064A\\u0637\\u0644\\u0639\\u0648\\u0627."
t["The equipment needs attention while there is still time to repair it."] = "\\u0627\\u0644\\u0639\\u062F\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0627\\u0647\\u062A\\u0645\\u0627\\u0645 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0641\\u064A \\u0648\\u0642\\u062A \\u0646\\u0635\\u0644\\u062D\\u0647\\u0627."
t["The example is clear. The conclusion needs work."] = "\\u0627\\u0644\\u0645\\u062B\\u0627\\u0644 \\u0648\\u0627\\u0636\\u062D. \\u0627\\u0644\\u0646\\u062A\\u064A\\u062C\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0634\\u063A\\u0644."
t["The exit is closing! Fall back!"] = "\\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0639\\u0645 \\u064A\\u062A\\u0633\\u0643\\u0631! \\u0627\\u0631\\u062C\\u0639!"
t["The exit's covered. I need another route."] = "\\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0645\\u0633\\u0643\\u0631. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["The farm tools are missing or broken."] = "\\u0639\\u062F\\u0629 \\u0627\\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0636\\u0627\\u064A\\u0639\\u0629 \\u0623\\u0648 \\u0645\\u0643\\u0633\\u0648\\u0631\\u0629."
t["The fence almost had me. Almost."] = "\\u0627\\u0644\\u0633\\u0648\\u0631 \\u0643\\u0627\\u0646 \\u0631\\u062D \\u064A\\u063A\\u0644\\u0628\\u0646\\u064A. \\u0643\\u0627\\u0646."
t["The fence says no. Loudly."] = "\\u0627\\u0644\\u0633\\u0648\\u0631 \\u0639\\u0645 \\u064A\\u0642\\u0648\\u0644 \\u0644\\u0623. \\u0648\\u0628\\u0635\\u0648\\u062A \\u0639\\u0627\\u0644\\u064A."
t["The fever is taking the room away from me."] = "\\u0627\\u0644\\u062D\\u0645\\u0649 \\u0639\\u0645 \\u062A\\u0627\\u062E\\u062F \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0645\\u0646 \\u0642\\u062F\\u0627\\u0645\\u064A."
t["The fever's climbing. I know what that means. I've read the notes."] = "\\u0627\\u0644\\u062D\\u0631\\u0627\\u0631\\u0629 \\u0639\\u0645 \\u062A\\u0637\\u0644\\u0639. \\u0648\\u0628\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u064A\\u0639\\u0646\\u064A. \\u0642\\u0631\\u064A\\u062A \\u0627\\u0644\\u0645\\u0644\\u0627\\u062D\\u0638\\u0627\\u062A."
t["The fish won't bite an empty hook. Can you find some bait?"] = "\\u0627\\u0644\\u0633\\u0645\\u0643 \\u0645\\u0627 \\u0628\\u064A\\u0639\\u0636 \\u0633\\u0646\\u0627\\u0631\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0641\\u064A\\u0643 \\u062A\\u0644\\u0627\\u0642\\u064A \\u0637\\u0639\\u0645\\u061F"
t["The floor creaks in the same place every time. It's becoming familiar."] = "\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0628\\u062A\\u0637\\u0642\\u0637\\u0642 \\u0628\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0643\\u0644 \\u0645\\u0631\\u0629. \\u0635\\u0631\\u062A \\u0622\\u0644\\u0641\\u0647\\u0627."
t["The floor wants me dead too. I'm finding level ground."] = "\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0643\\u0645\\u0627\\u0646 \\u0628\\u062F\\u0647\\u0627 \\u0645\\u0648\\u062A\\u064A. \\u0631\\u0627\\u064A\\u062D\\u0629 \\u0639\\u0645\\u0637\\u0631\\u062D \\u0645\\u0633\\u062A\\u0648\\u064A."
t["The fog decides how far the world goes today."] = "\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628 \\u0628\\u064A\\u0642\\u0631\\u0631 \\u0644\\u0648\\u064A\\u0646 \\u0628\\u062A\\u0648\\u0635\\u0644 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0627\\u0644\\u064A\\u0648\\u0645."
t["The food's here. The knife isn't."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0647\\u0648\\u0646. \\u0627\\u0644\\u0633\\u0643\\u064A\\u0646\\u0629 \\u0644\\u0623."
t["The food's ready to cook, but we have no heat."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u062C\\u0627\\u0647\\u0632 \\u0644\\u0644\\u0637\\u0628\\u062E\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u0639\\u0646\\u0627 \\u0646\\u0627\\u0631."
t["The form says final disposition pending. We can help with that part."] = "\\u0627\\u0644\\u0648\\u0631\\u0642\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0635\\u064A\\u0631 \\u0627\\u0644\\u0646\\u0647\\u0627\\u0626\\u064A \\u0645\\u0639\\u0644\\u0642. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0633\\u0627\\u0639\\u062F \\u0628\\u0647\\u0627\\u0644\\u062C\\u0632\\u0621."
t["The ground's hard enough with a shovel. Without one, forget it."] = "\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0642\\u0627\\u0633\\u064A\\u0629 \\u062D\\u062A\\u0649 \\u0645\\u0639 \\u0643\\u0631\\u064A\\u0643. \\u0628\\u0644\\u0627\\u0647\\u060C \\u0627\\u0646\\u0633\\u0649."
t["The group is working. Keep doing what works."] = "\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0645\\u0627\\u0634\\u064A\\u0629. \\u0643\\u0641\\u0651\\u0648\\u0627 \\u0639\\u0627\\u0644\\u0644\\u064A \\u0639\\u0645 \\u064A\\u0632\\u0628\\u0637."
t["The hammer is the missing piece here."] = "\\u0627\\u0644\\u0634\\u0627\\u0643\\u0648\\u0634 \\u0647\\u0648 \\u0627\\u0644\\u0646\\u0627\\u0642\\u0635 \\u0647\\u0648\\u0646."
t["The headache aisle looks popular. Can't imagine why."] = "\\u0642\\u0633\\u0645 \\u0648\\u062C\\u0639 \\u0627\\u0644\\u0631\\u0627\\u0633 \\u0634\\u0643\\u0644\\u0647 \\u0645\\u0637\\u0644\\u0648\\u0628. \\u0645\\u0648 \\u0639\\u0627\\u0631\\u0641\\u0629 \\u0644\\u064A\\u0634."
t["The hot dog roller's still rolling. No, it isn't. I just wish it was."] = "\\u0634\\u0648\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0646\\u0642\\u0627\\u0646\\u0642 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062A\\u062F\\u0648\\u0631. \\u0644\\u0623\\u060C \\u0645\\u0648 \\u0639\\u0645 \\u062A\\u062F\\u0648\\u0631. \\u0628\\u0633 \\u064A\\u0627 \\u0631\\u064A\\u062A."
t["The house stands. We are %1, and our supplies are %2."] = "\\u0627\\u0644\\u0628\\u064A\\u062A \\u0648\\u0627\\u0642\\u0641. \\u0646\\u062D\\u0646\\u0627 %1\\u060C \\u0648\\u0645\\u0648\\u0646\\u062A\\u0646\\u0627 %2."
t["The infection wins my body, not who I was."] = "\\u0627\\u0644\\u0639\\u062F\\u0648\\u0649 \\u0628\\u062A\\u0631\\u0628\\u062D \\u062C\\u0633\\u0645\\u064A, \\u0645\\u0648 \\u0627\\u0644\\u0644\\u064A \\u0643\\u0646\\u062A \\u064A\\u0627\\u0647."
t["The ingredients are ambitious. The stove is not."] = "\\u0627\\u0644\\u0645\\u0643\\u0648\\u0646\\u0627\\u062A \\u0637\\u0645\\u0648\\u062D\\u0629. \\u0627\\u0644\\u063A\\u0627\\u0632 \\u0644\\u0623."
t["The ingredients can wait. We need a pot first."] = "\\u0627\\u0644\\u0645\\u0643\\u0648\\u0646\\u0627\\u062A \\u0641\\u064A\\u0647\\u0627 \\u062A\\u0633\\u062A\\u0646\\u0649. \\u0623\\u0648\\u0644 \\u0634\\u064A \\u0627\\u0644\\u0637\\u0646\\u062C\\u0631\\u0629."
t["The job's ready. The saw isn't."] = "\\u0627\\u0644\\u0634\\u063A\\u0644 \\u062C\\u0627\\u0647\\u0632. \\u0627\\u0644\\u0645\\u0646\\u0634\\u0627\\u0631 \\u0644\\u0623."
t["The kettle has nothing left to say now."] = "\\u0627\\u0644\\u0625\\u0628\\u0631\\u064A\\u0642 \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0639\\u0646\\u062F\\u0648 \\u0634\\u064A \\u064A\\u0642\\u0648\\u0644\\u0647."
t["The last gap's closing. I'm taking it while it exists."] = "\\u0622\\u062E\\u0631 \\u0641\\u062A\\u062D\\u0629 \\u0639\\u0645 \\u062A\\u0633\\u0643\\u0631. \\u0628\\u0627\\u062E\\u062F\\u0647\\u0627 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0645\\u0648\\u062C\\u0648\\u062F\\u0629."
t["The last page changed how I read the first one."] = "\\u0622\\u062E\\u0631 \\u0635\\u0641\\u062D\\u0629 \\u063A\\u064A\\u0631\\u062A \\u0643\\u064A\\u0641 \\u0642\\u0631\\u064A\\u062A \\u0623\\u0648\\u0644 \\u0648\\u062D\\u062F\\u0629."
t["The last person I trust is the one who may have to stop me."] = "\\u0622\\u062E\\u0631 \\u062D\\u062F\\u0627 \\u0628\\u062B\\u0642 \\u0641\\u064A\\u0647 \\u0647\\u0648 \\u0627\\u0644\\u0644\\u064A \\u064A\\u0645\\u0643\\u0646 \\u064A\\u0636\\u0637\\u0631 \\u064A\\u0648\\u0642\\u0641\\u0646\\u064A."
t["The last quiet place in Knox County might be this hedge."] = "\\u0622\\u062E\\u0631 \\u0645\\u062D\\u0644 \\u0647\\u0627\\u062F\\u064A \\u0628\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0646\\u0648\\u0643\\u0633 \\u064A\\u0645\\u0643\\u0646 \\u0647\\u0627\\u0644\\u0633\\u064A\\u0627\\u062C."
t["The last traffic ticket in Kentucky is already written. Unpaid."] = "\\u0622\\u062E\\u0631 \\u0645\\u062E\\u0627\\u0644\\u0641\\u0629 \\u0633\\u064A\\u0631 \\u0628\\u0643\\u0646\\u062A\\u0627\\u0643\\u064A \\u0627\\u0646\\u0643\\u062A\\u0628\\u062A. \\u0648\\u0645\\u0627 \\u0627\\u0646\\u062A\\u062F\\u0641\\u0639\\u062A."
t["The librarian would shush the zombies. I'd pay to see it."] = "\\u0623\\u0645\\u064A\\u0646\\u0629 \\u0627\\u0644\\u0645\\u0643\\u062A\\u0628\\u0629 \\u0643\\u0627\\u0646\\u062A \\u0633\\u0643\\u0651\\u062A\\u062A \\u0627\\u0644\\u0632\\u0648\\u0645\\u0628\\u064A. \\u0628\\u062F\\u0641\\u0639 \\u0644\\u0634\\u0648\\u0641 \\u0647\\u0627\\u0644\\u0634\\u064A."
t["The light flickers like it remembers the owner."] = "\\u0627\\u0644\\u0636\\u0648 \\u0639\\u0645 \\u064A\\u0631\\u062C\\u0641 \\u0643\\u0623\\u0646\\u0648 \\u0645\\u062A\\u0630\\u0643\\u0631 \\u0635\\u0627\\u062D\\u0628 \\u0627\\u0644\\u0628\\u064A\\u062A."
t["The light leaves early now. Nothing asks it to stay."] = "\\u0627\\u0644\\u0636\\u0648 \\u0635\\u0627\\u0631 \\u064A\\u0631\\u0648\\u062D \\u0628\\u0643\\u064A\\u0631. \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0642\\u0644\\u0647 \\u0627\\u0633\\u062A\\u0646\\u0649."
t["The light's going. I'll make one more round of the camp."] = "\\u0627\\u0644\\u0636\\u0648 \\u0639\\u0645 \\u064A\\u0631\\u0648\\u062D. \\u0628\\u0639\\u0645\\u0644 \\u0643\\u0645\\u0627\\u0646 \\u0644\\u0641\\u0629 \\u0639\\u0627\\u0644\\u0645\\u062E\\u064A\\u0645."
t["The lights go out, but the chorus stays."] = "\\u0627\\u0644\\u0636\\u0648 \\u0628\\u064A\\u0646\\u0637\\u0641\\u064A\\u060C \\u0628\\u0633 \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0628\\u062A\\u0636\\u0644."
t["The line's moving. Let's settle this before it changes its mind."] = "\\u0627\\u0644\\u062E\\u064A\\u0637 \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u0635 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u063A\\u064A\\u0631 \\u0631\\u0623\\u064A\\u0647."
t["The locks held. The people didn't."] = "\\u0627\\u0644\\u0623\\u0642\\u0641\\u0627\\u0644 \\u0635\\u0645\\u062F\\u062A. \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0644\\u0623."
t["The map says home is this way. Maps have been wrong before."] = "\\u0627\\u0644\\u062E\\u0631\\u064A\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0645\\u0646 \\u0647\\u0648\\u0646. \\u0627\\u0644\\u062E\\u0631\\u0627\\u064A\\u0637 \\u063A\\u0644\\u0637\\u062A \\u0642\\u0628\\u0644."
t["The meal's possible, but we've nothing to portion it into."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0645\\u0645\\u0643\\u0646\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0646\\u0642\\u0633\\u0645\\u0647 \\u0641\\u064A\\u0647."
t["The middle of a book always makes me think harder than the beginning."] = "\\u0646\\u0635 \\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0628\\u064A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0641\\u0643\\u0631 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0623\\u0648\\u0644\\u0647."
t["The mirror behind the bottles makes this place look twice as disappointing."] = "\\u0627\\u0644\\u0645\\u0631\\u0627\\u064A\\u0629 \\u0648\\u0631\\u0627 \\u0627\\u0644\\u0642\\u0646\\u0627\\u0646\\u064A \\u0628\\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u062E\\u064A\\u0651\\u0628 \\u0645\\u0631\\u062A\\u064A\\u0646."
t["The mirror still looks tired, but at least it's clean."] = "\\u0627\\u0644\\u0645\\u0631\\u0627\\u064A\\u0629 \\u0644\\u0633\\u0627 \\u0634\\u0643\\u0644\\u0647\\u0627 \\u062A\\u0639\\u0628\\u0627\\u0646\\u060C \\u0628\\u0633 \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0646\\u0636\\u064A\\u0641\\u0629."
t["The news can wait. Our people cannot."] = "\\u0627\\u0644\\u0623\\u062E\\u0628\\u0627\\u0631 \\u0628\\u062A\\u0633\\u062A\\u0646\\u0649. \\u0646\\u0627\\u0633\\u0646\\u0627 \\u0645\\u0627 \\u0628\\u064A\\u0633\\u062A\\u0646\\u0648\\u0627."
t["The next blow ends whatever trust we had."] = "\\u0627\\u0644\\u0636\\u0631\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u062A\\u0646\\u0647\\u064A \\u0643\\u0644 \\u0627\\u0644\\u062B\\u0642\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0643\\u0627\\u0646\\u062A."
t["The nicotine is wearing off. I am getting twitchy."] = "\\u0627\\u0644\\u0646\\u064A\\u0643\\u0648\\u062A\\u064A\\u0646 \\u0639\\u0645 \\u064A\\u0631\\u0648\\u062D. \\u0639\\u0645 \\u0635\\u064A\\u0631 \\u0639\\u0635\\u0628\\u064A\\u0629."
t["The night swallowed every frequency I tried."] = "\\u0627\\u0644\\u0644\\u064A\\u0644 \\u0628\\u0644\\u0639 \\u0643\\u0644 \\u062A\\u0631\\u062F\\u062F \\u062C\\u0631\\u0628\\u062A\\u0647."
t["The notice promises orderly release. We may be a little outside office hours."] = "\\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646 \\u0628\\u064A\\u0648\\u0639\\u062F \\u0628\\u0625\\u062E\\u0644\\u0627\\u0621 \\u0645\\u0646\\u0638\\u0645. \\u064A\\u0645\\u0643\\u0646 \\u0646\\u062D\\u0646\\u0627 \\u0628\\u0631\\u0627 \\u0623\\u0648\\u0642\\u0627\\u062A \\u0627\\u0644\\u062F\\u0648\\u0627\\u0645 \\u0634\\u0648\\u064A."
t["The numbers want me dead. I'm finding a better angle."] = "\\u0627\\u0644\\u0623\\u0631\\u0642\\u0627\\u0645 \\u0628\\u062F\\u0647\\u0627 \\u0645\\u0648\\u062A\\u064A. \\u0639\\u0645 \\u062F\\u0648\\u0651\\u0631 \\u0639\\u0644\\u0649 \\u0632\\u0627\\u0648\\u064A\\u0629 \\u0623\\u062D\\u0633\\u0646."
t["The odds cost us somebody. I'm bringing myself back instead."] = "\\u0627\\u0644\\u062D\\u0633\\u0628\\u0629 \\u0643\\u0644\\u0641\\u062A\\u0646\\u0627 \\u0634\\u062E\\u0635. \\u0623\\u0646\\u0627 \\u0631\\u0627\\u062C\\u0639\\u0629 \\u0628\\u062F\\u0644 \\u0645\\u0627 \\u0646\\u062E\\u0633\\u0631 \\u063A\\u064A\\u0631\\u0647."
t["The old broadcasts still know a thing or two."] = "\\u0627\\u0644\\u0628\\u062B \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645 \\u0644\\u0633\\u0627 \\u0628\\u064A\\u0639\\u0631\\u0641 \\u0634\\u063A\\u0644\\u0629 \\u0623\\u0648 \\u062A\\u0646\\u062A\\u064A\\u0646."
t["The old days weren't perfect. They were ours."] = "\\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645\\u0629 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0643\\u0627\\u0645\\u0644\\u0629. \\u0628\\u0633 \\u0643\\u0627\\u0646\\u062A \\u0625\\u0644\\u0646\\u0627."
t["The old dressing is spent. I've got another."] = "\\u0627\\u0644\\u0636\\u0645\\u0627\\u062F \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645 \\u062E\\u0644\\u0635. \\u0645\\u0639\\u064A \\u063A\\u064A\\u0631\\u0647."
t["The old radio says the night is long..."] = "\\u0627\\u0644\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0627\\u0644\\u0639\\u062A\\u064A\\u0642 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0644\\u064A\\u0644 \\u0637\\u0648\\u064A\\u0644..."
t["The one my mother read to me. I still remember her voice."] = "\\u0627\\u0644\\u0644\\u064A \\u0643\\u0627\\u0646\\u062A \\u0623\\u0645\\u064A \\u062A\\u0642\\u0631\\u0627\\u0644\\u064A \\u064A\\u0627\\u0647\\u0627. \\u0644\\u0633\\u0627 \\u0628\\u062A\\u0630\\u0643\\u0631 \\u0635\\u0648\\u062A\\u0647\\u0627."
t["The opening is behind you. Use it."] = "\\u0627\\u0644\\u0641\\u062A\\u062D\\u0629 \\u0648\\u0631\\u0627\\u0643. \\u0627\\u0633\\u062A\\u063A\\u0644\\u0647\\u0627."
t["The order helps. I need the order today."] = "\\u0627\\u0644\\u062A\\u0631\\u062A\\u064A\\u0628 \\u0628\\u064A\\u0633\\u0627\\u0639\\u062F. \\u0627\\u0644\\u064A\\u0648\\u0645 \\u0645\\u062D\\u062A\\u0627\\u062C\\u062A\\u0647."
t["The paperwork survived. Of course the damn paperwork survived."] = "\\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062A \\u0639\\u0627\\u0634\\u062A. \\u0623\\u0643\\u064A\\u062F \\u064A\\u0644\\u0639\\u0646\\u0647\\u0627 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062A \\u0639\\u0627\\u0634\\u062A."
t["The paperwork survived. Of course the darn paperwork survived."] = "\\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062A \\u0639\\u0627\\u0634\\u062A. \\u0623\\u0643\\u064A\\u062F \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062A \\u0639\\u0627\\u0634\\u062A."
t["The picture is fuzzy, but I can follow it."] = "\\u0627\\u0644\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0634\\u0648\\u0634\\u0629\\u060C \\u0628\\u0633 \\u0645\\u0627\\u0634\\u064A\\u0629 \\u0645\\u0639\\u0647\\u0627."
t["The placard says the situation is under control. Strong wording for this room."] = "\\u0627\\u0644\\u0644\\u0648\\u062D\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0648\\u0636\\u0639 \\u062A\\u062D\\u062A \\u0627\\u0644\\u0633\\u064A\\u0637\\u0631\\u0629. \\u0643\\u0644\\u0627\\u0645 \\u0642\\u0648\\u064A \\u0644\\u0647\\u0627\\u0644\\u0623\\u0648\\u0636\\u0629."
t["The place has more faults than people. We'll catch up."] = "\\u0639\\u064A\\u0648\\u0628 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0633\\u0643\\u0627\\u0646\\u0647. \\u0631\\u062D \\u0646\\u0644\\u062D\\u0642 \\u0639\\u0644\\u064A\\u0647\\u0627."
t["The plan failed in specific ways. Let's name them."] = "\\u0627\\u0644\\u062E\\u0637\\u0629 \\u0641\\u0634\\u0644\\u062A \\u0628\\u0646\\u0642\\u0627\\u0637 \\u0645\\u062D\\u062F\\u062F\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u0645\\u064A\\u0647\\u0627."
t["The plan is sound if the cost stays lower than the reward."] = "\\u0627\\u0644\\u062E\\u0637\\u0629 \\u0633\\u0644\\u064A\\u0645\\u0629 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0627\\u0644\\u0643\\u0644\\u0641\\u0629 \\u0623\\u0642\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0643\\u0633\\u0628."
t["The plants did not make it. The ground still can."] = "\\u0627\\u0644\\u0632\\u0631\\u0639 \\u0645\\u0627 \\u0639\\u0627\\u0634. \\u0628\\u0633 \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0647\\u0627."
t["The plot is ready. Our tools are not."] = "\\u0627\\u0644\\u0623\\u0631\\u0636 \\u062C\\u0627\\u0647\\u0632\\u0629. \\u0639\\u062F\\u062A\\u0646\\u0627 \\u0644\\u0623."
t["The pole's still there. Don't tempt me."] = "\\u0627\\u0644\\u0639\\u0645\\u0648\\u062F \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646. \\u0644\\u0627 \\u062A\\u063A\\u0631\\u064A\\u0646\\u064A."
t["The porcelain throne still has a kingdom."] = "\\u0627\\u0644\\u0639\\u0631\\u0634 \\u0627\\u0644\\u0623\\u0628\\u064A\\u0636 \\u0644\\u0633\\u0627 \\u0625\\u0644\\u0647 \\u0645\\u0645\\u0644\\u0643\\u0629."
t["The pot's ready. The fire isn't."] = "\\u0627\\u0644\\u0637\\u0646\\u062C\\u0631\\u0629 \\u062C\\u0627\\u0647\\u0632\\u0629. \\u0627\\u0644\\u0646\\u0627\\u0631 \\u0644\\u0623."
t["The practical situation is:"] = "\\u0639\\u0645\\u0644\\u064A\\u0627\\u064B\\u060C \\u0627\\u0644\\u0648\\u0636\\u0639:"
t["The pump says pay inside. We can negotiate with the floor."] = "\\u0627\\u0644\\u0645\\u0636\\u062E\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u062F\\u0641\\u0639 \\u062C\\u0648\\u0627. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0641\\u0627\\u0648\\u0636 \\u0627\\u0644\\u0623\\u0631\\u0636."
t["The quiet in here is listening back."] = "\\u0627\\u0644\\u0633\\u0643\\u0648\\u062A \\u0647\\u0648\\u0646 \\u0639\\u0645 \\u064A\\u062A\\u0633\\u0645\\u0651\\u0639 \\u0639\\u0644\\u064A\\u0646\\u0627."
t["The quiet ones in the street were somebody's children."] = "\\u0627\\u0644\\u0633\\u0627\\u0643\\u062A\\u064A\\u0646 \\u0628\\u0627\\u0644\\u0634\\u0627\\u0631\\u0639 \\u0643\\u0627\\u0646\\u0648\\u0627 \\u0648\\u0644\\u0627\\u062F \\u062D\\u062F\\u0627."
t["The racks are empty. Somebody planned a long season."] = "\\u0627\\u0644\\u0631\\u0641\\u0648\\u0641 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u062D\\u062F\\u0627 \\u0645\\u062E\\u0637\\u0637 \\u0644\\u0645\\u0648\\u0633\\u0645 \\u0637\\u0648\\u064A\\u0644."
t["The radio had nothing to say. Fair enough."] = "\\u0627\\u0644\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0645\\u0627 \\u0639\\u0646\\u062F\\u0647 \\u0634\\u064A \\u064A\\u0642\\u0648\\u0644\\u0647. \\u0645\\u0627\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644."
t["The rain doesn't care who's left to stand in it."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0645\\u0627 \\u0628\\u064A\\u0647\\u0645\\u0647 \\u0645\\u064A\\u0646 \\u0636\\u0644 \\u0648\\u0627\\u0642\\u0641 \\u062A\\u062D\\u062A\\u0647."
t["The rain is washing a county that doesn't deserve it."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0639\\u0645 \\u064A\\u063A\\u0633\\u0644 \\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644."
t["The rain keeps tapping at the windows like it wants in."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0639\\u0645 \\u064A\\u062F\\u0642 \\u0639\\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643 \\u0643\\u0623\\u0646\\u0647 \\u0628\\u062F\\u0648 \\u064A\\u0641\\u0648\\u062A."
t["The rain makes every light in this room look warmer."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0643\\u0644 \\u0636\\u0648 \\u0628\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0623\\u062F\\u0641\\u0649."
t["The rain on the roof and the radio underneath it. Good enough."] = "\\u0645\\u0637\\u0631 \\u0639\\u0627\\u0644\\u0633\\u0637\\u062D \\u0648\\u0631\\u0627\\u062F\\u064A\\u0648 \\u062A\\u062D\\u062A\\u0647. \\u0628\\u0643\\u0641\\u064A."
t["The resemblance ends when somebody expects heroics."] = "\\u0627\\u0644\\u0634\\u0628\\u0647 \\u0628\\u064A\\u062E\\u0644\\u0635 \\u0644\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062A\\u0648\\u0642\\u0639 \\u0628\\u0637\\u0648\\u0644\\u0627\\u062A."
t["The restraints need checking before I lose control."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062A\\u0623\\u0643\\u062F \\u0645\\u0646 \\u0627\\u0644\\u0631\\u0628\\u0637\\u0627\\u062A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0641\\u0644\\u062A \\u0645\\u0646\\u064A \\u0627\\u0644\\u0632\\u0645\\u0627\\u0645."
t["The risk is settled. Quarantine them immediately."] = "\\u0627\\u0644\\u062E\\u0637\\u0631 \\u0645\\u062D\\u0633\\u0648\\u0645. \\u0627\\u0639\\u0632\\u0644\\u0648\\u0647\\u0646 \\u0641\\u0648\\u0631\\u0627\\u064B."
t["The river keeps its fish. I keep my wounded pride."] = "\\u0627\\u0644\\u0646\\u0647\\u0631 \\u0628\\u064A\\u062D\\u062A\\u0641\\u0638 \\u0628\\u0633\\u0645\\u0643\\u0647\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0628\\u0643\\u0631\\u0627\\u0645\\u062A\\u064A \\u0627\\u0644\\u0645\\u062C\\u0631\\u0648\\u062D\\u0629."
t["The river's pantry is mostly somebody else's pockets."] = "\\u0645\\u0648\\u0646\\u0629 \\u0627\\u0644\\u0646\\u0647\\u0631 \\u0623\\u063A\\u0644\\u0628\\u0647\\u0627 \\u0645\\u0646 \\u062C\\u064A\\u0628\\u0629 \\u063A\\u064A\\u0631\\u0646\\u0627."
t["The road doesn't care if we make it. Neither does the sky."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0627 \\u0628\\u064A\\u0647\\u0645\\u0647 \\u0646\\u0648\\u0635\\u0644. \\u0648\\u0644\\u0627 \\u0627\\u0644\\u0633\\u0645\\u0627."
t["The road doesn't give a damn if we make it. Neither does the sky."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0627 \\u0628\\u064A\\u0647\\u0645\\u0647 \\u0646\\u0648\\u0635\\u0644 \\u064A\\u0644\\u0639\\u0646\\u0647. \\u0648\\u0644\\u0627 \\u0627\\u0644\\u0633\\u0645\\u0627."
t["The road hasn't changed. We have."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0627 \\u062A\\u063A\\u064A\\u0631. \\u0646\\u062D\\u0646\\u0627 \\u062A\\u063A\\u064A\\u0631\\u0646\\u0627."
t["The road is long. This part should be short."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0637\\u0648\\u064A\\u0644. \\u0647\\u0627\\u0644\\u0642\\u0633\\u0645 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0643\\u0648\\u0646 \\u0642\\u0635\\u064A\\u0631."
t["The road let us go. I'm not going to ask why."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u062A\\u0631\\u0643\\u0646\\u0627. \\u0648\\u0645\\u0627 \\u0631\\u062D \\u0627\\u0633\\u0623\\u0644 \\u0644\\u064A\\u0634."
t["The road's a little clearer."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0646\\u0636\\u0641 \\u0634\\u0648\\u064A."
t["The road's quiet. I don't trust it."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0647\\u0627\\u062F\\u064A. \\u0648\\u0645\\u0627 \\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0647."
t["The roadside is lined with people who also had a plan."] = "\\u062C\\u0646\\u0628 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0644\\u064A\\u0627\\u0646 \\u0646\\u0627\\u0633 \\u0643\\u0645\\u0627\\u0646 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u0647\\u0645 \\u062E\\u0637\\u0629."
t["The rod's ready. The hook isn't."] = "\\u0627\\u0644\\u0642\\u0635\\u0628\\u0629 \\u062C\\u0627\\u0647\\u0632\\u0629. \\u0627\\u0644\\u0633\\u0646\\u0627\\u0631\\u0629 \\u0644\\u0623."
t["The room gets colder when the station goes quiet."] = "\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0628\\u062A\\u0628\\u0631\\u062F \\u0644\\u0645\\u0627 \\u0627\\u0644\\u0645\\u062D\\u0637\\u0629 \\u062A\\u0633\\u0643\\u062A."
t["The safe answer today could be the dangerous habit tomorrow."] = "\\u0627\\u0644\\u062C\\u0648\\u0627\\u0628 \\u0627\\u0644\\u0622\\u0645\\u0646 \\u0627\\u0644\\u064A\\u0648\\u0645 \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0635\\u064A\\u0631 \\u0639\\u0627\\u062F\\u0629 \\u062E\\u0637\\u0631\\u0629 \\u0628\\u0643\\u0631\\u0627."
t["The safety poster says every weapon has an owner. Applications are open."] = "\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0627\\u0644\\u0633\\u0644\\u0627\\u0645\\u0629 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0643\\u0644 \\u0633\\u0644\\u0627\\u062D \\u0625\\u0644\\u0648 \\u0635\\u0627\\u062D\\u0628. \\u0627\\u0644\\u0637\\u0644\\u0628\\u0627\\u062A \\u0645\\u0641\\u062A\\u0648\\u062D\\u0629."
t["The screen promises important public guidance. Concessions sold separately."] = "\\u0627\\u0644\\u0634\\u0627\\u0634\\u0629 \\u0628\\u062A\\u0648\\u0639\\u062F \\u0628\\u062A\\u0639\\u0644\\u064A\\u0645\\u0627\\u062A \\u0645\\u0647\\u0645\\u0629. \\u0627\\u0644\\u0628\\u0648\\u0634\\u0627\\u0631 \\u0639\\u0644\\u0649 \\u062D\\u0633\\u0627\\u0628\\u0643."
t["The screws are winning. I need a screwdriver."] = "\\u0627\\u0644\\u0628\\u0631\\u0627\\u063A\\u064A \\u0639\\u0645 \\u062A\\u0631\\u0628\\u062D. \\u0628\\u062F\\u064A \\u0645\\u0641\\u0643."
t["The season gets another swing at us. So do we."] = "\\u0627\\u0644\\u0645\\u0648\\u0633\\u0645 \\u0631\\u062D \\u064A\\u0636\\u0631\\u0628\\u0646\\u0627 \\u0636\\u0631\\u0628\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0648\\u0646\\u062D\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["The shaking stopped. I can think now."] = "\\u0648\\u0642\\u0641\\u062A \\u0627\\u0644\\u0631\\u062C\\u0641\\u0629. \\u0641\\u064A\\u0646\\u064A \\u0641\\u0643\\u0631 \\u0647\\u0644\\u0623."
t["The shelves are getting thin. When do we head out again?"] = "\\u0627\\u0644\\u0631\\u0641\\u0648\\u0641 \\u0639\\u0645 \\u062A\\u0641\\u0636\\u0649. \\u0625\\u064A\\u0645\\u062A \\u0645\\u0646\\u0637\\u0644\\u0639 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629\\u061F"
t["The shower still works. I'm taking my chance."] = "\\u0627\\u0644\\u062F\\u0648\\u0634 \\u0644\\u0633\\u0627 \\u0634\\u063A\\u0627\\u0644. \\u0631\\u062D \\u0627\\u0633\\u062A\\u063A\\u0644 \\u0627\\u0644\\u0641\\u0631\\u0635\\u0629."
t["The sign promises fast service in any crisis. Self-service counts."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0648\\u0639\\u062F \\u0628\\u062E\\u062F\\u0645\\u0629 \\u0633\\u0631\\u064A\\u0639\\u0629 \\u0628\\u0623\\u064A \\u0623\\u0632\\u0645\\u0629. \\u0627\\u0644\\u062E\\u062F\\u0645\\u0629 \\u0627\\u0644\\u0630\\u0627\\u062A\\u064A\\u0629 \\u0628\\u062A\\u0646\\u062D\\u0633\\u0628."
t["The sign says 'Serve and Protect'. Somebody should tell the sign."] = "\\u0645\\u0643\\u062A\\u0648\\u0628: \\u0646\\u062E\\u062F\\u0645 \\u0648\\u0646\\u062D\\u0645\\u064A. \\u062D\\u062F\\u0627 \\u064A\\u062E\\u0628\\u0631 \\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629."
t["The sign says drink responsibly. At last, an instruction still in force."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0634\\u0631\\u0628 \\u0628\\u0645\\u0633\\u0624\\u0648\\u0644\\u064A\\u0629. \\u0623\\u062E\\u064A\\u0631\\u064B\\u0627\\u060C \\u062A\\u0639\\u0644\\u064A\\u0645\\u0627\\u062A \\u0644\\u0633\\u0627 \\u0633\\u0627\\u0631\\u064A\\u0629."
t["The sign says every bucket brings folks together. Bring a can opener."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0643\\u0644 \\u0633\\u0637\\u0644 \\u0628\\u064A\\u062C\\u0645\\u0639 \\u0627\\u0644\\u0646\\u0627\\u0633. \\u062C\\u064A\\u0628 \\u0641\\u062A\\u0651\\u0627\\u062D\\u0629 \\u0639\\u0644\\u0628."
t["The signal crossed a lot of empty roads to get here."] = "\\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0642\\u0637\\u0639\\u062A \\u0637\\u0631\\u0642\\u0627\\u062A \\u0641\\u0627\\u0636\\u064A\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u062A\\u0648\\u0635\\u0644."
t["The signal faded, but I caught the important part."] = "\\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0631\\u0627\\u062D\\u062A\\u060C \\u0628\\u0633 \\u0644\\u062D\\u0642\\u062A \\u0627\\u0644\\u0645\\u0647\\u0645."
t["The signal fades in and out like headlights in fog."] = "\\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0628\\u062A\\u0631\\u0648\\u062D \\u0648\\u062A\\u062C\\u064A \\u0645\\u062A\\u0644 \\u0636\\u0648 \\u0633\\u064A\\u0627\\u0631\\u0629 \\u0628\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628."
t["The signal is holding. Might as well see the end."] = "\\u0627\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u062B\\u0627\\u0628\\u062A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0627\\u0644\\u0646\\u0647\\u0627\\u064A\\u0629."
t["The signal is weak, but it made it through."] = "\\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0636\\u0639\\u064A\\u0641\\u0629\\u060C \\u0628\\u0633 \\u0648\\u0635\\u0644\\u062A."
t["The signal made it through the walls and the weather."] = "\\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0645\\u0631\\u0642\\u062A \\u0645\\u0646 \\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0648\\u0627\\u0644\\u0637\\u0642\\u0633."
t["The soil is getting dry."] = "\\u0627\\u0644\\u062A\\u0631\\u0627\\u0628 \\u0639\\u0645 \\u064A\\u0646\\u0634\\u0641."
t["The sound carried down the hall like a light under a door."] = "\\u0627\\u0644\\u0635\\u0648\\u062A \\u0646\\u0632\\u0644 \\u0639\\u0627\\u0644\\u0645\\u0645\\u0631 \\u0645\\u062A\\u0644 \\u0636\\u0648 \\u0645\\u0646 \\u062A\\u062D\\u062A \\u0628\\u0627\\u0628."
t["The speaker crackled, but the point came through."] = "\\u0627\\u0644\\u0633\\u0645\\u0627\\u0639\\u0629 \\u0637\\u0642\\u0637\\u0642\\u062A\\u060C \\u0628\\u0633 \\u0627\\u0644\\u0641\\u0643\\u0631\\u0629 \\u0648\\u0635\\u0644\\u062A."
t["The spot is defensible, as long as nobody blocks the retreat."] = "\\u0627\\u0644\\u0645\\u062D\\u0644 \\u064A\\u0646\\u062D\\u0645\\u0649\\u060C \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0643\\u0651\\u0631 \\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0627\\u0646\\u0633\\u062D\\u0627\\u0628."
t["The stars don't know anything happened."] = "\\u0627\\u0644\\u0646\\u062C\\u0648\\u0645 \\u0645\\u0627 \\u0628\\u062A\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u0635\\u0627\\u0631."
t["The static almost swallowed that last part."] = "\\u0627\\u0644\\u062A\\u0634\\u0648\\u064A\\u0634 \\u0643\\u0627\\u0646 \\u0631\\u062D \\u064A\\u0628\\u0644\\u0639 \\u0622\\u062E\\u0631 \\u0642\\u0633\\u0645."
t["The station is still breathing. So are we."] = "\\u0627\\u0644\\u0645\\u062D\\u0637\\u0629 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062A\\u062A\\u0646\\u0641\\u0633. \\u0648\\u0646\\u062D\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["The station went quiet before I did."] = "\\u0627\\u0644\\u0645\\u062D\\u0637\\u0629 \\u0633\\u0643\\u062A\\u062A \\u0642\\u0628\\u0644\\u064A."
t["The stir fry has no pan. That's a structural problem."] = "\\u0627\\u0644\\u0642\\u0644\\u064A\\u0629 \\u0628\\u0644\\u0627 \\u0645\\u0642\\u0644\\u0627\\u064A\\u0629. \\u0647\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0628\\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u0627\\u062A."
t["The stove's ready. I'm missing a pan."] = "\\u0627\\u0644\\u063A\\u0627\\u0632 \\u062C\\u0627\\u0647\\u0632. \\u0646\\u0627\\u0642\\u0635\\u062A\\u0646\\u064A \\u0645\\u0642\\u0644\\u0627\\u064A\\u0629."
t["The stream's strong. My aim's seen better days."] = "\\u0627\\u0644\\u0636\\u062E \\u0642\\u0648\\u064A. \\u062A\\u0635\\u0648\\u064A\\u0628\\u064A \\u0634\\u0627\\u0641 \\u0623\\u064A\\u0627\\u0645 \\u0623\\u062D\\u0633\\u0646."
t["The street is full! Fight your way out!"] = "\\u0627\\u0644\\u0634\\u0627\\u0631\\u0639 \\u0645\\u0644\\u064A\\u0627\\u0646! \\u0642\\u0627\\u062A\\u0644 \\u0644\\u062A\\u0637\\u0644\\u0639!"
t["The street is lost! Run!"] = "\\u0627\\u0644\\u0634\\u0627\\u0631\\u0639 \\u0631\\u0627\\u062D! \\u0627\\u0631\\u0643\\u0636!"
t["The supplies are labeled. You'll manage."] = "\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0645\\u0643\\u062A\\u0648\\u0628 \\u0639\\u0644\\u064A\\u0647\\u0627. \\u0631\\u062D \\u062A\\u062F\\u0628\\u0631 \\u062D\\u0627\\u0644\\u0643."
t["The supplies are sorted, the doors hold, and I can finally breathe."] = "\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0645\\u0631\\u062A\\u0628\\u0629\\u060C \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0635\\u0627\\u0645\\u062F\\u0629\\u060C \\u0648\\u0623\\u062E\\u064A\\u0631\\u0627\\u064B \\u0639\\u0645 \\u0627\\u062A\\u0646\\u0641\\u0633."
t["The torch is empty. I can't do this yet."] = "\\u0627\\u0644\\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0641\\u0627\\u0636\\u064A. \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0647\\u0644\\u0623."
t["The towel deposit seems difficult to collect now."] = "\\u062A\\u0623\\u0645\\u064A\\u0646 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0634\\u0641 \\u0635\\u0639\\u0628 \\u064A\\u062A\\u062D\\u0635\\u0644 \\u0647\\u0644\\u0623."
t["The trees can keep this secret."] = "\\u0627\\u0644\\u0634\\u062C\\u0631 \\u0628\\u064A\\u0643\\u062A\\u0645 \\u0647\\u0627\\u0644\\u0633\\u0631."
t["The trees won this round. We still need an axe."] = "\\u0627\\u0644\\u0634\\u062C\\u0631 \\u0631\\u0628\\u062D \\u0647\\u0627\\u0644\\u062C\\u0648\\u0644\\u0629. \\u0644\\u0633\\u0627 \\u0628\\u062F\\u0646\\u0627 \\u0641\\u0627\\u0633."
t["The trial is over. I want to remain with your group."] = "\\u062E\\u0644\\u0635\\u062A \\u0627\\u0644\\u062A\\u062C\\u0631\\u0628\\u0629. \\u0628\\u062F\\u064A \\u0636\\u0644 \\u0645\\u0639 \\u062C\\u0645\\u0627\\u0639\\u062A\\u0643."
t["The useful answer is:"] = "\\u0627\\u0644\\u062C\\u0648\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0641\\u064A\\u062F:"
t["The wall is waiting on a hammer. So am I."] = "\\u0627\\u0644\\u062D\\u064A\\u0637 \\u0646\\u0627\\u0637\\u0631 \\u0634\\u0627\\u0643\\u0648\\u0634. \\u0648\\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["The wall remains where it was. So do I."] = "\\u0627\\u0644\\u062D\\u064A\\u0637 \\u0628\\u0639\\u062F\\u0647 \\u0645\\u0637\\u0631\\u062D\\u0647. \\u0648\\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["The wall's still standing, and the stain isn't."] = "\\u0627\\u0644\\u062D\\u064A\\u0637 \\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641\\u060C \\u0648\\u0627\\u0644\\u0628\\u0642\\u0639\\u0629 \\u0644\\u0623."
t["The walls make me feel caged, not safe. Odd thought."] = "\\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0628\\u062A\\u062D\\u0633\\u0633\\u0646\\u064A \\u0645\\u062D\\u0628\\u0648\\u0633\\u0629\\u060C \\u0645\\u0648 \\u0628\\u0623\\u0645\\u0627\\u0646. \\u0641\\u0643\\u0631\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629."
t["The watch continues, even after losing %1. Keep this conversation brief."] = "\\u0627\\u0644\\u062D\\u0631\\u0627\\u0633\\u0629 \\u0645\\u0633\\u062A\\u0645\\u0631\\u0629\\u060C \\u062D\\u062A\\u0649 \\u0628\\u0639\\u062F \\u0645\\u0627 \\u062E\\u0633\\u0631\\u0646\\u0627 %1. \\u062E\\u0644\\u064A \\u0627\\u0644\\u062D\\u0643\\u064A \\u0642\\u0635\\u064A\\u0631."
t["The water is full of surprises. Mostly garbage."] = "\\u0627\\u0644\\u0645\\u064A \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629 \\u0645\\u0641\\u0627\\u062C\\u0622\\u062A. \\u0623\\u063A\\u0644\\u0628\\u0647\\u0627 \\u0632\\u0628\\u0627\\u0644\\u0629."
t["The water's there, but our fishing gear isn't."] = "\\u0627\\u0644\\u0645\\u064A \\u0647\\u0648\\u0646\\u060C \\u0628\\u0633 \\u0639\\u062F\\u0629 \\u0627\\u0644\\u0635\\u064A\\u062F \\u0644\\u0623."
t["The way back is crawling. We need another exit."] = "\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0631\\u062C\\u0639\\u0629 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629. \\u0628\\u062F\\u0646\\u0627 \\u0645\\u062E\\u0631\\u062C \\u062A\\u0627\\u0646\\u064A."
t["The windows are dark now. At least we're together."] = "\\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643 \\u0639\\u062A\\u0645\\u062A. \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0646\\u062D\\u0646\\u0627 \\u0633\\u0648\\u0627."
t["The work can wait five minutes. How are your hands holding up?"] = "\\u0627\\u0644\\u0634\\u063A\\u0644 \\u0628\\u064A\\u0633\\u062A\\u0646\\u0649 \\u062E\\u0645\\u0633 \\u062F\\u0642\\u0627\\u064A\\u0642. \\u0643\\u064A\\u0641 \\u0625\\u064A\\u062F\\u064A\\u0643\\u061F"
t["The world came through in pieces, but it came through."] = "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0648\\u0635\\u0644\\u062A \\u0642\\u0637\\u0639 \\u0642\\u0637\\u0639\\u060C \\u0628\\u0633 \\u0648\\u0635\\u0644\\u062A."
t["The world ended, but an argument can still have two sides."] = "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062E\\u0644\\u0635\\u062A\\u060C \\u0628\\u0633 \\u0627\\u0644\\u0646\\u0642\\u0627\\u0634 \\u0644\\u0633\\u0627 \\u0625\\u0644\\u0647 \\u0637\\u0631\\u0641\\u064A\\u0646."
t["The world got quiet. The dial did not."] = "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0633\\u0643\\u062A\\u062A. \\u0627\\u0644\\u0645\\u0624\\u0634\\u0631 \\u0644\\u0623."
t["The world is bigger than this house. The radio remembers."] = "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0623\\u0643\\u0628\\u0631 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0628\\u064A\\u062A. \\u0627\\u0644\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0644\\u0633\\u0627 \\u0645\\u062A\\u0630\\u0643\\u0631."
t["The world switches off and my head switches on."] = "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0628\\u062A\\u0646\\u0637\\u0641\\u064A \\u0648\\u0631\\u0627\\u0633\\u064A \\u0628\\u064A\\u0634\\u062A\\u063A\\u0644."
t["The world's ending at a very leisurely pace here."] = "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0639\\u0645 \\u062A\\u062E\\u0644\\u0635 \\u0647\\u0648\\u0646 \\u0639\\u0627\\u0644\\u0628\\u0637\\u064A\\u0621 \\u0648\\u0628\\u0643\\u0644 \\u0631\\u0627\\u062D\\u0629."
t["The worst part is leaving you to face tomorrow without me."] = "\\u0623\\u0635\\u0639\\u0628 \\u0634\\u064A \\u0625\\u0646\\u064A \\u062E\\u0644\\u064A\\u0643 \\u062A\\u0648\\u0627\\u062C\\u0647 \\u0628\\u0643\\u0631\\u0627 \\u0628\\u0644\\u0627\\u064A."
t["The wound is ugly, but I can cover it."] = "\\u0627\\u0644\\u062C\\u0631\\u062D \\u0628\\u0634\\u0639\\u060C \\u0628\\u0633 \\u0641\\u064A\\u0646\\u064A \\u063A\\u0637\\u064A\\u0647."
t["The writer makes a bold claim. I almost believe it."] = "\\u0627\\u0644\\u0643\\u0627\\u062A\\u0628 \\u0639\\u0645 \\u064A\\u0642\\u0648\\u0644 \\u062D\\u0643\\u064A \\u062C\\u0631\\u064A\\u0621. \\u0634\\u0648\\u064A \\u0648\\u0628\\u0635\\u062F\\u0642\\u0647."
t["Their line keeps growing. I'm retreating before it reaches me."] = "\\u062E\\u0637\\u0647\\u0646 \\u0639\\u0645 \\u064A\\u0643\\u0628\\u0631. \\u0639\\u0645 \\u0627\\u0646\\u0633\\u062D\\u0628 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0648\\u0635\\u0644\\u0646\\u064A."
t["Their loss. I had a whole encore."] = "\\u0647\\u0646\\u0646 \\u0627\\u0644\\u062E\\u0633\\u0631\\u0627\\u0646\\u064A\\u0646. \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u0641\\u0642\\u0631\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["Their numbers exceed my reach. Creating distance."] = "\\u0639\\u062F\\u062F\\u0647\\u0646 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0637\\u0648\\u0644\\u0629 \\u0625\\u064A\\u062F\\u064A. \\u0639\\u0645 \\u0641\\u062A\\u062D \\u0645\\u0633\\u0627\\u0641\\u0629."
t["Then I'll judge the kettle after one sip."] = "\\u0637\\u064A\\u0628 \\u0628\\u062D\\u0643\\u0645 \\u0639\\u0627\\u0644\\u0625\\u0628\\u0631\\u064A\\u0642 \\u0628\\u0639\\u062F \\u0623\\u0648\\u0644 \\u0631\\u0634\\u0641\\u0629."
t["Then this is goodbye. Stay alive."] = "\\u064A\\u0639\\u0646\\u064A \\u0647\\u0627\\u062F \\u0627\\u0644\\u0648\\u062F\\u0627\\u0639. \\u0636\\u0644 \\u0639\\u0627\\u064A\\u0634."
t["Then we do it together. I'll be ready."] = "\\u0647\\u064A\\u0643 \\u0645\\u0646\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0633\\u0648\\u0627. \\u0631\\u062D \\u0643\\u0648\\u0646 \\u062C\\u0627\\u0647\\u0632\\u0629."
t["Then we stretch the supplies and keep our eyes open."] = "\\u0647\\u064A\\u0643 \\u0645\\u0646\\u0645\\u0637\\u0651 \\u0628\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0648\\u0645\\u0646\\u0636\\u0644 \\u0645\\u0641\\u062A\\u062D\\u064A\\u0646."
t["Then we take turns. Nobody has to lose a day waiting."] = "\\u0637\\u064A\\u0628 \\u0645\\u0646\\u062A\\u0646\\u0627\\u0648\\u0628. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0636\\u064A\\u0639 \\u0646\\u0647\\u0627\\u0631 \\u0648\\u0647\\u0648 \\u0645\\u0633\\u062A\\u0646\\u064A."
t["There are four of them. This keeps getting worse."] = "\\u0647\\u062F\\u0648\\u0644 \\u0623\\u0631\\u0628\\u0639\\u0629. \\u0648\\u0627\\u0644\\u0648\\u0636\\u0639 \\u0639\\u0645 \\u064A\\u0632\\u0641\\u062A \\u0623\\u0643\\u062A\\u0631."
t["There are four! Keep them off me!"] = "\\u0647\\u062F\\u0648\\u0644 \\u0623\\u0631\\u0628\\u0639\\u0629! \\u0628\\u0639\\u062F\\u0646 \\u0639\\u0646\\u064A!"
t["There are people at the other end. There have to be."] = "\\u0641\\u064A \\u0646\\u0627\\u0633 \\u0639\\u0627\\u0644\\u0637\\u0631\\u0641 \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A. \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0643\\u0648\\u0646 \\u0641\\u064A."
t["There are things I wish I had said to %1 while there was time."] = "\\u0641\\u064A \\u062D\\u0643\\u064A \\u0643\\u0646\\u062A \\u0627\\u062A\\u0645\\u0646\\u0649 \\u0642\\u0648\\u0644\\u0647 \\u0644\\u0640 %1 \\u0644\\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0641\\u064A \\u0648\\u0642\\u062A."
t["There are too many. There are way too many."] = "\\u0643\\u062A\\u0627\\u0631 \\u0643\\u062A\\u064A\\u0631. \\u0648\\u0627\\u0644\\u0644\\u0647 \\u0643\\u062A\\u064A\\u0631 \\u0643\\u062A\\u064A\\u0631."
t["There aren't enough bowls for the soup."] = "\\u0645\\u0627 \\u0641\\u064A \\u0632\\u0628\\u0627\\u062F\\u064A \\u0643\\u0641\\u0627\\u064A\\u0629 \\u0644\\u0644\\u0634\\u0648\\u0631\\u0628\\u0629."
t["There is a keepsake I left behind. I still think about recovering it."] = "\\u0641\\u064A \\u062A\\u0630\\u0643\\u0627\\u0631 \\u062A\\u0631\\u0643\\u062A\\u0647 \\u0648\\u0631\\u0627\\u064A\\u064A. \\u0648\\u0644\\u0633\\u0627 \\u0628\\u0641\\u0643\\u0631 \\u062C\\u064A\\u0628\\u0647."
t["There is a light at the far end of the dial."] = "\\u0641\\u064A \\u0636\\u0648 \\u0628\\u0622\\u062E\\u0631 \\u0627\\u0644\\u0645\\u0624\\u0634\\u0631."
t["There is a method in there, underneath the static."] = "\\u0641\\u064A \\u0637\\u0631\\u064A\\u0642\\u0629 \\u062C\\u0648\\u0627\\u060C \\u062A\\u062D\\u062A \\u0627\\u0644\\u062A\\u0634\\u0648\\u064A\\u0634."
t["There is a radio on up here. I'll sit and listen."] = "\\u0641\\u064A \\u0631\\u0627\\u062F\\u064A\\u0648 \\u0634\\u063A\\u0627\\u0644 \\u0647\\u0648\\u0646 \\u0641\\u0648\\u0642. \\u0628\\u0642\\u0639\\u062F \\u0648\\u0627\\u0633\\u0645\\u0639."
t["There is enough here to share."] = "\\u0641\\u064A \\u0647\\u0648\\u0646 \\u0634\\u064A \\u0628\\u064A\\u0643\\u0641\\u064A \\u0627\\u0644\\u0643\\u0644."
t["There is no point hiding it:"] = "\\u0645\\u0627 \\u0641\\u064A \\u0641\\u0627\\u064A\\u062F\\u0629 \\u0646\\u062E\\u0628\\u064A:"
t["There is room for everyone now. Real room."] = "\\u0641\\u064A \\u0645\\u062D\\u0644 \\u0644\\u0644\\u0643\\u0644 \\u0647\\u0644\\u0623. \\u0645\\u062D\\u0644 \\u0639\\u0646 \\u062C\\u062F."
t["There is something in these walls. I can feel it."] = "\\u0641\\u064A \\u0634\\u064A \\u0628\\u0647\\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646. \\u062D\\u0627\\u0633\\u0629 \\u0641\\u064A\\u0647."
t["There is something you need to see. It's a bite."] = "\\u0641\\u064A \\u0634\\u064A \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0634\\u0648\\u0641\\u0647. \\u0647\\u064A \\u0639\\u0636\\u0629."
t["There is still someone keeping the lights on somewhere."] = "\\u0644\\u0633\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0636\\u0648 \\u0634\\u063A\\u0627\\u0644 \\u0628\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0627."
t["There used to be music here. I remember the tune."] = "\\u0643\\u0627\\u0646 \\u0641\\u064A \\u0645\\u0648\\u0633\\u064A\\u0642\\u0649 \\u0647\\u0648\\u0646. \\u0644\\u0633\\u0627 \\u0645\\u062A\\u0630\\u0643\\u0631\\u0629 \\u0627\\u0644\\u0644\\u062D\\u0646."
t["There was a bird on the sill this morning. Just watching us."] = "\\u0643\\u0627\\u0646 \\u0641\\u064A \\u0639\\u0635\\u0641\\u0648\\u0631 \\u0639\\u0627\\u0644\\u0634\\u0628\\u0627\\u0643 \\u0627\\u0644\\u0635\\u0628\\u062D. \\u0628\\u0633 \\u0639\\u0645 \\u064A\\u062A\\u0641\\u0631\\u062C \\u0639\\u0644\\u064A\\u0646\\u0627."
t["There was a diner outside town. The coffee was terrible. I miss it."] = "\\u0643\\u0627\\u0646 \\u0641\\u064A \\u0645\\u0637\\u0639\\u0645 \\u0628\\u0631\\u0627 \\u0627\\u0644\\u0628\\u0644\\u062F. \\u0627\\u0644\\u0642\\u0647\\u0648\\u0629 \\u062A\\u0628\\u0639\\u0647 \\u0632\\u0641\\u062A. \\u0627\\u0634\\u062A\\u0642\\u062A\\u0644\\u0647."
t["There was a train through Riverside once..."] = "\\u0643\\u0627\\u0646 \\u0641\\u064A \\u0642\\u0637\\u0627\\u0631 \\u0628\\u064A\\u0645\\u0631\\u0642 \\u0645\\u0646 \\u0631\\u064A\\u0641\\u0631\\u0633\\u0627\\u064A\\u062F..."
t["There was a way home from this. You ended it."] = "\\u0643\\u0627\\u0646 \\u0641\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0644\\u0644\\u0628\\u064A\\u062A \\u0645\\u0646 \\u0647\\u0648\\u0646. \\u0625\\u0646\\u062A \\u0633\\u0643\\u0631\\u062A\\u0647."
t["There was still so much road left."] = "\\u0643\\u0627\\u0646 \\u0644\\u0633\\u0627 \\u0641\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0637\\u0648\\u064A\\u0644."
t["There we go. Something has it."] = "\\u0625\\u064A\\u0648\\u0627. \\u0641\\u064A \\u0634\\u064A \\u0639\\u0644\\u0642."
t["There you go. Drink up."] = "\\u062A\\u0641\\u0636\\u0644\\u0648\\u0627. \\u0627\\u0634\\u0631\\u0628\\u0648\\u0627."
t["There! Again. You heard that, right?"] = "\\u0647\\u0646\\u064A\\u0643! \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0633\\u0645\\u0639\\u062A\\u0647\\u0627\\u060C \\u0635\\u062D\\u061F"
t["There's a part here about grief. Can I tell you about it, %1?"] = "\\u0641\\u064A \\u0642\\u0633\\u0645 \\u0647\\u0648\\u0646 \\u0639\\u0646 \\u0627\\u0644\\u062D\\u0632\\u0646. \\u0641\\u064A\\u0646\\u064A \\u0627\\u062D\\u0643\\u064A\\u0644\\u0643 \\u0639\\u0646\\u0647 \\u064A\\u0627 %1\\u061F"
t["There's a person in these pages who needed someone to listen."] = "\\u0641\\u064A \\u0625\\u0646\\u0633\\u0627\\u0646 \\u0628\\u0647\\u0627\\u0644\\u0635\\u0641\\u062D\\u0627\\u062A \\u0643\\u0627\\u0646 \\u0645\\u062D\\u062A\\u0627\\u062C \\u062D\\u062F\\u0627 \\u064A\\u0633\\u0645\\u0639\\u0647."
t["There's a sale sign. Finally, prices that match our wages."] = "\\u0641\\u064A \\u064A\\u0627\\u0641\\u0637\\u0629 \\u062A\\u0646\\u0632\\u064A\\u0644\\u0627\\u062A. \\u0623\\u062E\\u064A\\u0631\\u064B\\u0627 \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0639\\u0644\\u0649 \\u0642\\u062F \\u0645\\u0639\\u0627\\u0634\\u0627\\u062A\\u0646\\u0627."
t["There's a warning buried in this chapter. I'm keeping it."] = "\\u0641\\u064A \\u062A\\u062D\\u0630\\u064A\\u0631 \\u0645\\u062E\\u0628\\u0649 \\u0628\\u0647\\u0627\\u0644\\u0641\\u0635\\u0644. \\u0631\\u062D \\u0627\\u062D\\u062A\\u0641\\u0638 \\u0641\\u064A\\u0647."
t["There's bread to slice and no knife to do it with."] = "\\u0641\\u064A \\u062E\\u0628\\u0632 \\u0628\\u062F\\u0648 \\u062A\\u0642\\u0637\\u064A\\u0639 \\u0648\\u0645\\u0627 \\u0641\\u064A \\u0633\\u0643\\u064A\\u0646\\u0629."
t["There's daylight enough for one mistake. Let's make none."] = "\\u0627\\u0644\\u0636\\u0648 \\u0628\\u0643\\u0641\\u064A \\u0644\\u063A\\u0644\\u0637\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0627 \\u0646\\u063A\\u0644\\u0637."
t["There's dirt in places the sun has forgotten."] = "\\u0641\\u064A \\u0648\\u0633\\u062E \\u0628\\u0623\\u0645\\u0627\\u0643\\u0646 \\u0627\\u0644\\u0634\\u0645\\u0633 \\u0646\\u0633\\u064A\\u062A\\u0647\\u0627."
t["There's food to fry, but nothing to fry it in."] = "\\u0641\\u064A \\u0623\\u0643\\u0644 \\u0628\\u062F\\u0648 \\u0642\\u0644\\u064A \\u0648\\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0646\\u0642\\u0644\\u064A \\u0641\\u064A\\u0647."
