t["This body is done. I am not ashamed of it."] = "\\u0647\\u0627\\u0644\\u062C\\u0633\\u0645 \\u062E\\u0644\\u0635. \\u0648\\u0645\\u0648 \\u062E\\u062C\\u0644\\u0627\\u0646\\u0629 \\u0645\\u0646\\u0647."
t["This book gets better when it stops repeating itself."] = "\\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0628\\u064A\\u062A\\u062D\\u0633\\u0646 \\u0644\\u0645\\u0627 \\u064A\\u0628\\u0637\\u0644 \\u064A\\u0639\\u064A\\u062F \\u062D\\u0627\\u0644\\u0647."
t["This book made me think of you, %1. In a good way."] = "\\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0630\\u0643\\u0631\\u0646\\u064A \\u0641\\u064A\\u0643 \\u064A\\u0627 %1. \\u0628\\u0627\\u0644\\u0645\\u0646\\u064A\\u062D."
t["This book says courage can be learned. What do you think, %1?"] = "\\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0634\\u062C\\u0627\\u0639\\u0629 \\u0628\\u062A\\u0646\\u062A\\u0639\\u0644\\u0645. \\u0634\\u0648 \\u0631\\u0623\\u064A\\u0643 \\u064A\\u0627 %1\\u061F"
t["This book says prepare for the worst. How far is too far, %1?"] = "\\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0633\\u062A\\u0639\\u062F \\u0644\\u0644\\u0623\\u0633\\u0648\\u0623. \\u0644\\u0648\\u064A\\u0646 \\u0627\\u0644\\u062D\\u062F \\u064A\\u0627 %1\\u061F"
t["This camp has a better retirement plan than my old job."] = "\\u0647\\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0639\\u0646\\u062F\\u0648 \\u062A\\u0642\\u0627\\u0639\\u062F \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0634\\u063A\\u0644\\u064A \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645."
t["This camp has a spine now. I like it."] = "\\u0647\\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0635\\u0627\\u0631 \\u0625\\u0644\\u0647 \\u0636\\u0647\\u0631. \\u0639\\u062C\\u0628\\u0646\\u064A."
t["This chair has a better story than the road today."] = "\\u0647\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0639\\u0646\\u062F\\u0647 \\u0642\\u0635\\u0629 \\u0623\\u062D\\u0644\\u0649 \\u0645\\u0646 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u064A\\u0648\\u0645."
t["This chapter gave me a question I didn't have yesterday."] = "\\u0647\\u0627\\u0644\\u0641\\u0635\\u0644 \\u0639\\u0637\\u0627\\u0646\\u064A \\u0633\\u0624\\u0627\\u0644 \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u0645\\u0628\\u0627\\u0631\\u062D."
t["This chapter has a fight in it, even without weapons."] = "\\u0647\\u0627\\u0644\\u0641\\u0635\\u0644 \\u0641\\u064A\\u0647 \\u062E\\u0646\\u0627\\u0642\\u0629\\u060C \\u062D\\u062A\\u0649 \\u0628\\u0644\\u0627 \\u0633\\u0644\\u0627\\u062D."
t["This corner needs work. I've got it."] = "\\u0647\\u0627\\u0644\\u0632\\u0627\\u0648\\u064A\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0634\\u063A\\u0644. \\u0639\\u0644\\u064A\\u0651."
t["This could be useful. Keep that part in mind."] = "\\u0647\\u0627\\u062F \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0641\\u064A\\u062F. \\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u0646\\u0642\\u0637\\u0629 \\u0628\\u0628\\u0627\\u0644\\u0643."
t["This crop is gone. I'll clear it and start again."] = "\\u0631\\u0627\\u062D \\u0647\\u0627\\u0644\\u0632\\u0631\\u0639. \\u0631\\u062D \\u0646\\u0636\\u0651\\u0641\\u0647 \\u0648\\u0628\\u0628\\u0644\\u0651\\u0634 \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F."
t["This crop is ready."] = "\\u0647\\u0627\\u0644\\u0632\\u0631\\u0639 \\u062C\\u0627\\u0647\\u0632."
t["This crop is sick. I'll treat it."] = "\\u0647\\u0627\\u0644\\u0632\\u0631\\u0639 \\u0645\\u0631\\u064A\\u0636. \\u0631\\u062D \\u0639\\u0627\\u0644\\u062C\\u0647."
t["This ditch has seen worse days than mine."] = "\\u0647\\u0627\\u0644\\u062E\\u0646\\u062F\\u0642 \\u0634\\u0627\\u0641 \\u0623\\u064A\\u0627\\u0645 \\u0623\\u0633\\u0648\\u0623 \\u0645\\u0646 \\u0623\\u064A\\u0627\\u0645\\u064A."
t["This does not buy you entry:"] = "\\u0647\\u0627\\u062F \\u0645\\u0627 \\u0628\\u064A\\u0641\\u0648\\u0651\\u062A\\u0643 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A:"
t["This feels like a big one."] = "\\u0634\\u0643\\u0644\\u0647\\u0627 \\u0643\\u0628\\u064A\\u0631\\u0629 \\u0647\\u064A."
t["This fight is over if you let it be."] = "\\u0647\\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0628\\u064A\\u062E\\u0644\\u0635 \\u0625\\u0630\\u0627 \\u0628\\u062A\\u062E\\u0644\\u064A\\u0647."
t["This firearm will not help much without more ammunition."] = "\\u0647\\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u0645\\u0627 \\u0628\\u064A\\u0646\\u0641\\u0639 \\u0643\\u062A\\u064A\\u0631 \\u0628\\u0644\\u0627 \\u0631\\u0635\\u0627\\u0635."
t["This fog is bad. Short steps, frequent checks."] = "\\u0647\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628 \\u0639\\u0627\\u0637\\u0644. \\u062E\\u0637\\u0648\\u0627\\u062A \\u0642\\u0635\\u064A\\u0631\\u0629 \\u0648\\u0645\\u0646\\u062A\\u0637\\u0644\\u0639 \\u0643\\u0644 \\u0634\\u0648\\u064A."
t["This ground is next."] = "\\u0647\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0627\\u0644\\u062F\\u0648\\u0631."
t["This group is tougher than any of us expected."] = "\\u0647\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0623\\u0642\\u0648\\u0649 \\u0645\\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639 \\u0623\\u064A \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0627."
t["This hydrant's had a worse week than me."] = "\\u0647\\u0627\\u0644\\u062D\\u0646\\u0641\\u064A\\u0629 \\u0645\\u0631\\u0642\\u062A \\u0639\\u0644\\u064A\\u0647\\u0627 \\u062C\\u0645\\u0639\\u0629 \\u0623\\u0633\\u0648\\u0623 \\u0645\\u0646\\u064A."
t["This is a check, nothing urgent. Everybody copy?"] = "\\u0647\\u0627\\u062F \\u0641\\u062D\\u0635\\u060C \\u0645\\u0648 \\u0634\\u064A \\u0645\\u0633\\u062A\\u0639\\u062C\\u0644. \\u0627\\u0644\\u0643\\u0644 \\u0648\\u0627\\u0635\\u0644\\u0647\\u061F"
t["This is a trial. We both get to judge how it goes."] = "\\u0647\\u064A \\u062A\\u062C\\u0631\\u0628\\u0629. \\u0646\\u062D\\u0646\\u0627 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646\\u062D\\u0643\\u0645 \\u0643\\u064A\\u0641 \\u0628\\u062A\\u0645\\u0634\\u064A."
t["This is all we are saying:"] = "\\u0647\\u0627\\u062F \\u0643\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0631\\u062D \\u0646\\u0642\\u0648\\u0644\\u0647:"
t["This is bad. I need to eat."] = "\\u0627\\u0644\\u0648\\u0636\\u0639 \\u0639\\u0627\\u0637\\u0644. \\u0644\\u0627\\u0632\\u0645 \\u0622\\u0643\\u0644."
t["This is becoming a pack."] = "\\u0647\\u0627\\u062F \\u0639\\u0645 \\u064A\\u0635\\u064A\\u0631 \\u0642\\u0637\\u064A\\u0639."
t["This is getting dangerous. We need an exit plan now."] = "\\u0635\\u0627\\u0631\\u062A \\u062E\\u0637\\u0631\\u0629. \\u0628\\u062F\\u0646\\u0627 \\u062E\\u0637\\u0629 \\u0647\\u0631\\u0648\\u0628 \\u0647\\u0644\\u0623."
t["This is going to sting. Better than leaving it open."] = "\\u0631\\u062D \\u062A\\u062D\\u0631\\u0642\\u0643 \\u0634\\u0648\\u064A. \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u062A\\u0631\\u0643\\u0647\\u0627 \\u0645\\u0641\\u062A\\u0648\\u062D\\u0629."
t["This is not helping. We need an answer, not another argument."] = "\\u0647\\u064A\\u0643 \\u0645\\u0627 \\u0628\\u064A\\u0646\\u0641\\u0639. \\u0628\\u062F\\u0646\\u0627 \\u062C\\u0648\\u0627\\u0628\\u060C \\u0645\\u0648 \\u062E\\u0646\\u0627\\u0642\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["This is past an empty stomach. I need a meal."] = "\\u0647\\u0627\\u062F \\u0635\\u0627\\u0631 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0639\\u062F\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0628\\u062F\\u064A \\u0648\\u062C\\u0628\\u0629."
t["This is still better than a crowded motel bathroom."] = "\\u0644\\u0633\\u0627 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u062D\\u0645\\u0627\\u0645 \\u0645\\u0648\\u062A\\u064A\\u0644 \\u0645\\u0632\\u062F\\u062D\\u0645."
t["This is taking too long!"] = "\\u0639\\u0645 \\u064A\\u0627\\u062E\\u062F \\u0648\\u0642\\u062A \\u0643\\u062A\\u064A\\u0631!"
t["This is the place. Spread out and see what we can carry."] = "\\u0647\\u0648\\u0646 \\u0627\\u0644\\u0645\\u062D\\u0644. \\u062A\\u0648\\u0632\\u0639\\u0648\\u0627 \\u0648\\u0634\\u0648\\u0641\\u0648\\u0627 \\u0634\\u0648 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0645\\u0644."
t["This is too close. I am starting to lose it."] = "\\u0647\\u0627\\u062F \\u0642\\u0631\\u064A\\u0628 \\u0643\\u062A\\u064A\\u0631. \\u0639\\u0645 \\u0627\\u0628\\u0644\\u0634 \\u0627\\u0641\\u0642\\u062F \\u0623\\u0639\\u0635\\u0627\\u0628\\u064A."
t["This is turning bad. I'm pulling back."] = "\\u0627\\u0644\\u0648\\u0636\\u0639 \\u0639\\u0645 \\u064A\\u062E\\u0631\\u0628. \\u0639\\u0645 \\u0627\\u0646\\u0633\\u062D\\u0628."
t["This is unsafe. I need water before we move."] = "\\u0647\\u0627\\u062F \\u0645\\u0648 \\u0622\\u0645\\u0646. \\u0628\\u062F\\u064A \\u0645\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u062A\\u062D\\u0631\\u0643."
t["This is what your warnings bought you!"] = "\\u0647\\u0627\\u062F \\u0627\\u0644\\u0644\\u064A \\u0637\\u0644\\u0639\\u0644\\u0643 \\u0645\\u0646 \\u0643\\u0644 \\u0627\\u0644\\u062A\\u062D\\u0630\\u064A\\u0631\\u0627\\u062A!"
t["This is where I draw the line. Stay back."] = "\\u0644\\u0647\\u0648\\u0646 \\u0648\\u0628\\u0633. \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F."
t["This is your last chance to walk away."] = "\\u0647\\u064A \\u0622\\u062E\\u0631 \\u0641\\u0631\\u0635\\u0629 \\u0625\\u0644\\u0643 \\u0644\\u062A\\u0645\\u0634\\u064A."
t["This isn't a secret you get to keep."] = "\\u0647\\u0627\\u062F \\u0645\\u0648 \\u0633\\u0631 \\u0645\\u0646 \\u062D\\u0642\\u0643 \\u062A\\u062E\\u0628\\u064A\\u0647."
t["This isn't worth losing someone over. I'm coming back."] = "\\u0645\\u0627 \\u0628\\u062A\\u0633\\u0648\\u0649 \\u0646\\u062E\\u0633\\u0631 \\u062D\\u062F\\u0627 \\u0639\\u0634\\u0627\\u0646\\u0647\\u0627. \\u0631\\u0627\\u062C\\u0639\\u0629."
t["This job needs a working screwdriver."] = "\\u0647\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0645\\u0641\\u0643 \\u0634\\u063A\\u0651\\u0627\\u0644."
t["This job stops until we have the right tool."] = "\\u0647\\u0627\\u0644\\u0634\\u063A\\u0644 \\u0648\\u0627\\u0642\\u0641 \\u0644\\u062D\\u062A\\u0649 \\u064A\\u0635\\u064A\\u0631 \\u0645\\u0639\\u0646\\u0627 \\u0627\\u0644\\u0639\\u062F\\u0629 \\u0627\\u0644\\u0635\\u062D."
t["This life is not for me. I am returning to the house."] = "\\u0647\\u0627\\u0644\\u0639\\u064A\\u0634\\u0629 \\u0645\\u0648 \\u0625\\u0644\\u064A. \\u0631\\u0627\\u062C\\u0639\\u0629 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
t["This needs a review, not another excuse."] = "\\u0647\\u0627\\u062F \\u0628\\u062F\\u0648 \\u0645\\u0631\\u0627\\u062C\\u0639\\u0629\\u060C \\u0645\\u0648 \\u062D\\u062C\\u0629 \\u062C\\u062F\\u064A\\u062F\\u0629."
t["This needs a working saw."] = "\\u0647\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0634\\u063A\\u0651\\u0627\\u0644."
t["This needs a working, fueled blowtorch."] = "\\u0647\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0634\\u063A\\u0651\\u0627\\u0644 \\u0648\\u0645\\u0639\\u0628\\u0651\\u0649."
t["This part reminded me of someone I'd rather not forget."] = "\\u0647\\u0627\\u0644\\u0645\\u0642\\u0637\\u0639 \\u0630\\u0643\\u0631\\u0646\\u064A \\u0628\\u062D\\u062F\\u0627 \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0646\\u0633\\u0627\\u0647."
t["This patch is below its water target."] = "\\u0647\\u0627\\u0644\\u0634\\u0642\\u0641\\u0629 \\u0645\\u064A \\u0623\\u0642\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645."
t["This patch is picked clean."] = "\\u0647\\u0627\\u0644\\u0634\\u0642\\u0641\\u0629 \\u0627\\u0646\\u0642\\u0637\\u0641\\u062A \\u0643\\u0644\\u0647\\u0627."
t["This patch needs treatment."] = "\\u0647\\u0627\\u0644\\u0634\\u0642\\u0641\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0639\\u0644\\u0627\\u062C."
t["This place is finally starting to work like a real camp."] = "\\u0623\\u062E\\u064A\\u0631\\u0627\\u064B \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0639\\u0645 \\u064A\\u0635\\u064A\\u0631 \\u0645\\u062A\\u0644 \\u0645\\u062E\\u064A\\u0645 \\u0639\\u0646 \\u062C\\u062F."
t["This place is ours now. Let's make it look that way."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0635\\u0627\\u0631 \\u0625\\u0644\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u064A\\u0647 \\u064A\\u0628\\u064A\\u0646 \\u0647\\u064A\\u0643."
t["This place needs a cat. Someone to look after."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u062F\\u0648 \\u0642\\u0637\\u0629. \\u062D\\u062F\\u0627 \\u0646\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0646\\u0627 \\u0639\\u0644\\u064A\\u0647."
t["This place remembers more people than it holds."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u064A\\u062A\\u0630\\u0643\\u0631 \\u0646\\u0627\\u0633 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0641\\u064A\\u0647."
t["This place smells like every bad decision I made before '93."] = "\\u0631\\u064A\\u062D\\u0629 \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u062A\\u0644 \\u0643\\u0644 \\u0642\\u0631\\u0627\\u0631 \\u063A\\u0644\\u0637 \\u0627\\u062A\\u062E\\u0630\\u062A\\u0647 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u064093."
t["This place will outlast us. It's a real smug bastard about it, too."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0631\\u062D \\u064A\\u0639\\u064A\\u0634 \\u0628\\u0639\\u062F\\u0646\\u0627. \\u0648\\u0645\\u062A\\u0634\\u0627\\u0648\\u0641 \\u0639\\u0644\\u064A\\u0646\\u0627 \\u0627\\u0628\\u0646 \\u0627\\u0644\\u0643\\u0644\\u0628."
t["This place will outlast us. It's rude about it, too."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0631\\u062D \\u064A\\u0639\\u064A\\u0634 \\u0628\\u0639\\u062F\\u0646\\u0627. \\u0648\\u0642\\u0644\\u064A\\u0644 \\u0627\\u0644\\u0630\\u0648\\u0642 \\u0643\\u0645\\u0627\\u0646."
t["This position can work, but I am keeping an eye on the exits."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u064A\\u0645\\u0634\\u064A\\u060C \\u0628\\u0633 \\u0639\\u064A\\u0646\\u064A \\u0639\\u0627\\u0644\\u0645\\u062E\\u0627\\u0631\\u062C."
t["This position is lost. You are not."] = "\\u0647\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0631\\u0627\\u062D. \\u0625\\u0646\\u062A \\u0644\\u0623."
t["This position won't let me work. I'll need a clear place."] = "\\u0647\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644. \\u0628\\u062F\\u064A \\u0645\\u0637\\u0631\\u062D \\u0641\\u0627\\u0636\\u064A."
t["This pressure is getting to me."] = "\\u0647\\u0627\\u0644\\u0636\\u063A\\u0637 \\u0639\\u0645 \\u064A\\u0637\\u0644\\u0639 \\u0639\\u0644\\u064A\\u064A."
t["This room feels wrong as heck. Watch those corners."] = "\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u063A\\u0644\\u0637 \\u0643\\u062A\\u064A\\u0631 \\u0648\\u0627\\u0644\\u0644\\u0647. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627."
t["This room feels wrong as hell. Watch those corners."] = "\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u063A\\u0644\\u0637 \\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627."
t["This room has a voice. I want to hear it properly."] = "\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0625\\u0644\\u0647\\u0627 \\u0635\\u0648\\u062A. \\u0628\\u062F\\u064A \\u0627\\u0633\\u0645\\u0639\\u0647 \\u0645\\u0646\\u064A\\u062D."
t["This room has the atmosphere of a sealed coffin."] = "\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u062C\\u0648\\u0647\\u0627 \\u0645\\u062A\\u0644 \\u062A\\u0627\\u0628\\u0648\\u062A \\u0645\\u0633\\u0643\\u0651\\u0631."
t["This room is quiet enough to talk. How are you holding up, %1?"] = "\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0647\\u0627\\u062F\\u064A\\u0629 \\u0643\\u0641\\u0627\\u064A\\u0629 \\u0644\\u0646\\u062D\\u0643\\u064A. \\u0643\\u064A\\u0641\\u0643 \\u064A\\u0627 %1\\u061F"
t["This room still smells a little like coffee after the fire goes out."] = "\\u0647\\u0627\\u0644\\u0623\\u0648\\u0636\\u0629 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0647\\u0627 \\u0631\\u064A\\u062D\\u0629 \\u0642\\u0647\\u0648\\u0629 \\u0628\\u0639\\u062F \\u0645\\u0627 \\u062A\\u0646\\u0637\\u0641\\u064A \\u0627\\u0644\\u0646\\u0627\\u0631."
t["This room's smaller than my chances. I'm heading outside."] = "\\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0623\\u0635\\u063A\\u0631 \\u0645\\u0646 \\u0641\\u0631\\u0635\\u064A. \\u0637\\u0627\\u0644\\u0639\\u0629 \\u0628\\u0631\\u0627."
t["This row failed. I'm clearing it before it spreads."] = "\\u0647\\u0627\\u0644\\u062E\\u0637 \\u0641\\u0634\\u0644. \\u0639\\u0645 \\u0634\\u064A\\u0644\\u0647 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0646\\u062A\\u0634\\u0631."
t["This row finally paid us back."] = "\\u0623\\u062E\\u064A\\u0631\\u0627\\u064B \\u0647\\u0627\\u0644\\u062E\\u0637 \\u0631\\u062C\\u0651\\u0639\\u0644\\u0646\\u0627 \\u062A\\u0639\\u0628\\u0646\\u0627."
t["This row needs a drink."] = "\\u0647\\u0627\\u0644\\u062E\\u0637 \\u0639\\u0637\\u0634\\u0627\\u0646."
t["This shelter needs another layer of defense."] = "\\u0647\\u0627\\u0644\\u0645\\u0644\\u062C\\u0623 \\u0628\\u062F\\u0647 \\u0637\\u0628\\u0642\\u0629 \\u062D\\u0645\\u0627\\u064A\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["This station used to come in clear after dark."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0637\\u0629 \\u0643\\u0627\\u0646\\u062A \\u062A\\u062C\\u064A \\u0648\\u0627\\u0636\\u062D\\u0629 \\u0628\\u0639\\u062F \\u0627\\u0644\\u0639\\u062A\\u0645\\u0629."
t["This stays at the gate:"] = "\\u0647\\u0627\\u062F \\u0628\\u064A\\u0636\\u0644 \\u0639\\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629:"
t["This stew needs a pot. I'm still looking for one."] = "\\u0647\\u0627\\u0644\\u0637\\u0628\\u062E\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0637\\u0646\\u062C\\u0631\\u0629. \\u0648\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062F\\u0648\\u0631."
t["This story made a lonely person feel seen. Does that sound foolish, %1?"] = "\\u0647\\u0627\\u0644\\u0642\\u0635\\u0629 \\u062E\\u0644\\u062A \\u0625\\u0646\\u0633\\u0627\\u0646 \\u0648\\u062D\\u064A\\u062F \\u064A\\u062D\\u0633 \\u062D\\u062F\\u0627 \\u0634\\u0627\\u064A\\u0641\\u0647. \\u0628\\u062A\\u0637\\u0644\\u0639 \\u0633\\u062E\\u064A\\u0641\\u0629 \\u064A\\u0627 %1\\u061F"
t["This table reminds me of one my grandmother kept under a yellow lamp."] = "\\u0647\\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629 \\u0628\\u062A\\u0630\\u0643\\u0631\\u0646\\u064A \\u0628\\u0648\\u062D\\u062F\\u0629 \\u0643\\u0627\\u0646\\u062A \\u0639\\u0646\\u062F \\u0633\\u062A\\u064A \\u062A\\u062D\\u062A \\u0644\\u0645\\u0628\\u0629 \\u0635\\u0641\\u0631\\u0627."
t["This table used to mean supper. What would you put on it tonight, %1?"] = "\\u0647\\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629 \\u0643\\u0627\\u0646\\u062A \\u062A\\u0639\\u0646\\u064A \\u0639\\u0634\\u0627. \\u0634\\u0648 \\u0628\\u062A\\u062D\\u0637 \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629 \\u064A\\u0627 %1\\u061F"
t["This tastes like a kitchen that doesn't exist anymore."] = "\\u0637\\u0639\\u0645\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0645\\u0637\\u0628\\u062E \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0645\\u0648\\u062C\\u0648\\u062F."
t["This team still needs both of us. Pull me out!"] = "\\u0647\\u0627\\u0644\\u0641\\u0631\\u064A\\u0642 \\u0644\\u0633\\u0627 \\u0628\\u062F\\u0647 \\u062A\\u0646\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627. \\u0627\\u0633\\u062D\\u0628\\u0646\\u064A!"
t["This thing's nearly broken. I'm not trusting my life to it."] = "\\u0647\\u0627\\u0644\\u0634\\u064A \\u0642\\u0631\\u0628 \\u064A\\u0646\\u0643\\u0633\\u0631. \\u0645\\u0648 \\u0631\\u062D \\u0633\\u0644\\u0645\\u0647 \\u062D\\u064A\\u0627\\u062A\\u064A."
t["This thing's writing its will. I'm finding a replacement."] = "\\u0647\\u0627\\u0644\\u0634\\u064A \\u0639\\u0645 \\u064A\\u0643\\u062A\\u0628 \\u0648\\u0635\\u064A\\u062A\\u0647. \\u0639\\u0645 \\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0628\\u062F\\u064A\\u0644."
t["This way! I've got a pulse and terrible judgment!"] = "\\u0644\\u0647\\u0648\\u0646! \\u0645\\u0639\\u064A \\u0646\\u0628\\u0636 \\u0648\\u0639\\u0642\\u0644 \\u062E\\u0631\\u0628\\u0627\\u0646!"
t["This weapon won't survive that fight."] = "\\u0647\\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u0645\\u0648 \\u0631\\u062D \\u064A\\u0639\\u064A\\u0634 \\u0647\\u0627\\u0644\\u0642\\u062A\\u0627\\u0644."
